def decode(self, encoding, field: str='strict', dtype: str | DtypeObj | None=None):
    if dtype is not None and (not is_string_dtype(dtype)):
        raise ValueError(f'dtype must be string or object, got dtype={dtype!r}')
    if dtype is None and using_string_dtype():
        dtype = 'str'
    if encoding in _cpython_optimized_decoders:
        f = lambda x: x.decode(encoding, field)
    else:
        decoder = codecs.getdecoder(encoding)
        f = lambda x: decoder(x, field)[0]
    arr = self._data.array
    result = arr._str_map(f)
    return self._wrap_result(result, dtype=dtype)

