def hermroots(c):
    [c] = pu.as_series([c])
    if len(c) <= 1:
        return np.array([], dtype=c.dtype)
    if len(c) == 2:
        return np.array([-0.5 * c[0] / c[1]])
    m = hermcompanion(c)[::-1, ::-1]
    r = np.linalg.eigvals(m)
    r.sort()
    from numpy.linalg._linalg import _to_real_if_imag_zero
    r = _to_real_if_imag_zero(r, m)
    return r

