@validate_params({'n_samples': [Interval(Integral, 1, None, closed='left')], 'n_features': [Interval(Integral, 1, None, closed='left')], 'n_classes': [Interval(Integral, 1, None, closed='left')], 'n_labels': [Interval(Integral, 0, None, closed='left')], 'length': [Interval(Integral, 1, None, closed='left')], 'allow_unlabeled': ['boolean'], 'sparse': ['boolean'], 'return_indicator': [StrOptions({'dense', 'sparse'}), 'boolean'], 'return_distributions': ['boolean'], 'random_state': ['random_state']}, prefer_skip_nested_validation=True)
def make_multilabel_classification(n_samples=100, n_features=20, *, n_classes=5, n_labels=2, length=50, allow_unlabeled=True, sparse=False, return_indicator='dense', return_distributions=False, random_state=None):
    generator = check_random_state(random_state)
    p_c = generator.uniform(size=n_classes)
    p_c /= p_c.sum()
    cumulative_p_c = np.cumsum(p_c)
    p_w_c = generator.uniform(size=(n_features, n_classes))
    p_w_c /= np.sum(p_w_c, axis=0)

    def sample_example():
        _, n_classes = p_w_c.shape
        y_size = n_classes + 1
        while not allow_unlabeled and y_size == 0 or y_size > n_classes:
            y_size = generator.poisson(n_labels)
        y = set()
        while len(y) != y_size:
            c = np.searchsorted(cumulative_p_c, generator.uniform(size=y_size - len(y)))
            y.update(c)
        y = list(y)
        n_words = 0
        while n_words == 0:
            n_words = generator.poisson(length)
        if len(y) == 0:
            words = generator.randint(n_features, size=n_words)
            return (words, y)
        cumulative_p_w_sample = p_w_c.take(y, axis=1).sum(axis=1).cumsum()
        cumulative_p_w_sample /= cumulative_p_w_sample[-1]
        words = np.searchsorted(cumulative_p_w_sample, generator.uniform(size=n_words))
        return (words, y)
    X_indices = array.array('i')
    X_indptr = array.array('i', [0])
    Y = []
    for i in range(n_samples):
        words, y = sample_example()
        X_indices.extend(words)
        X_indptr.append(len(X_indices))
        Y.append(y)
    X_data = np.ones(len(X_indices), dtype=np.float64)
    X = sp.csr_array((X_data, X_indices, X_indptr), shape=(n_samples, n_features))
    X.sum_duplicates()
    if not sparse:
        X = X.toarray()
    else:
        X = _align_api_if_sparse(X)
    if return_indicator in (True, 'sparse', 'dense'):
        lb = MultiLabelBinarizer(sparse_output=return_indicator == 'sparse')
        Y = lb.fit([range(n_classes)]).transform(Y)
    if return_distributions:
        return (X, Y, p_c, p_w_c)
    return (X, Y)

def read(self, nrows: int | None=None) -> DataFrame:
    if self.engine == 'pyarrow':
        try:
            df = self._engine.read()
        except Exception:
            self.close()
            raise
    else:
        nrows = validate_integer('nrows', nrows)
        try:
            index, columns, col_dict = self._engine.read(nrows)
        except Exception:
            self.close()
            raise
        if index is None:
            if col_dict:
                new_rows = len(next(iter(col_dict.values())))
                index = RangeIndex(self._currow, self._currow + new_rows)
            else:
                new_rows = 0
        else:
            new_rows = len(index)
        if hasattr(self, 'orig_options'):
            dtype_arg = self.orig_options.get('dtype', None)
        else:
            dtype_arg = None
        if isinstance(dtype_arg, dict):
            dtype = defaultdict(lambda: None)
            dtype.update(dtype_arg)
        elif dtype_arg is not None and pandas_dtype(dtype_arg) in (np.str_, np.object_):
            dtype = defaultdict(lambda: dtype_arg)
        else:
            dtype = None
        if dtype is not None:
            new_col_dict = {}
            for k, v in col_dict.items():
                d = dtype[k] if pandas_dtype(dtype[k]) in (np.str_, np.object_) else None
                new_col_dict[k] = Series(v, index=index, dtype=d, copy=False)
        else:
            new_col_dict = col_dict
        df = DataFrame(new_col_dict, columns=columns, index=index, copy=False)
        self._currow += new_rows
    return df

def get_descendants(self, file_path):
    if len(file_path) == 1:
        return [self]
    if file_path[1] not in self.children:
        return [self, None]
    return [self] + self.children[file_path[1]].get_descendants(file_path[1:])

@pytest.fixture(params=[key for key, value in indices_dict.items() if not (key.startswith(('int', 'uint', 'float')) or key in ['range', 'empty', 'repeats', 'bool-dtype']) and (not isinstance(value, MultiIndex))])
def index_with_missing(request):
