@set_module('numpy')
def hanning(M):
    values = np.array([0.0, M])
    M = values[1]
    if M < 1:
        return array([], dtype=values.dtype)
    if M == 1:
        return ones(1, dtype=values.dtype)
    n = arange(1 - M, M, 2)
    return 0.5 + 0.5 * cos(pi * n / (M - 1))

def _get_column_indices(X, key):
    key_dtype = _determine_key_type(key)
    if nw.dependencies.is_into_dataframe(X):
        df_nw = nw.from_native(X)
        n_columns = df_nw.shape[1]
        column_names = df_nw.columns
    else:
        n_columns = X.shape[1]
        column_names = None
    if isinstance(key, (list, tuple)) and (not key):
        return []
    elif key_dtype in ('bool', 'int'):
        return _get_column_indices_for_bool_or_int(key, n_columns)
    else:
        if column_names is None:
            raise ValueError('Specifying the columns using strings is only supported for dataframes.')
        if isinstance(key, slice):
            if key.step not in [1, None]:
                raise NotImplementedError('key.step must be 1 or None')
            start, stop = (key.start, key.stop)
            if start is not None:
                start = column_names.index(start)
            if stop is not None:
                stop = column_names.index(stop) + 1
            else:
                stop = n_columns + 1
            return list(islice(range(n_columns), start, stop))
        else:
            selected_columns = [key] if np.isscalar(key) else key
            try:
                return [column_names.index(col) for col in selected_columns]
            except ValueError as e:
                missing = {*selected_columns} - {*column_names}
                msg = f'Some column names are not columns of the dataframe: {missing}'
                raise ValueError(msg) from e

def _fill_zeros(result: np.ndarray, x, y) -> np.ndarray:
    if result.dtype.kind == 'f':
        return result
    is_variable_type = hasattr(y, 'dtype')
    is_scalar_type = not isinstance(y, np.ndarray)
    if not is_variable_type and (not is_scalar_type):
        return result
    if is_scalar_type:
        y = np.array(y)
    if y.dtype.kind in 'iu':
        ymask = y == 0
        if ymask.any():
            mask = ymask & ~np.isnan(result)
            result = result.astype('float64', copy=False)
            np.putmask(result, mask, np.nan)
    return result

