def _compute_precision_cholesky_from_precisions(precisions, covariance_type, xp=None):
    if covariance_type == 'full':
        precisions_cholesky = xp.stack([_flipudlr(_cholesky(_flipudlr(precisions[i, :, :], xp=xp), xp=xp), xp=xp) for i in range(precisions.shape[0])])
    elif covariance_type == 'tied':
        precisions_cholesky = _flipudlr(_cholesky(_flipudlr(precisions, xp=xp), xp=xp), xp=xp)
    else:
        precisions_cholesky = xp.sqrt(precisions)
    return precisions_cholesky

