def log_marginal_likelihood(self, theta=None, eval_gradient=False, clone_kernel=True):
    if theta is None:
        if eval_gradient:
            raise ValueError('Gradient can only be evaluated for theta!=None')
        return self.log_marginal_likelihood_value_
    if clone_kernel:
        kernel = self.kernel_.clone_with_theta(theta)
    else:
        kernel = self.kernel_
        kernel.theta = theta
    if eval_gradient:
        K, K_gradient = kernel(self.X_train_, eval_gradient=True)
    else:
        K = kernel(self.X_train_)
    Z, (pi, W_sr, L, b, a) = self._posterior_mode(K, return_temporaries=True)
    if not eval_gradient:
        return Z
    d_Z = np.empty(theta.shape[0])
    R = W_sr[:, np.newaxis] * cho_solve((L, True), np.diag(W_sr))
    C = solve(L, W_sr[:, np.newaxis] * K)
    s_2 = -0.5 * (np.diag(K) - np.einsum('ij, ij -> j', C, C)) * (pi * (1 - pi) * (1 - 2 * pi))
    for j in range(d_Z.shape[0]):
        C = K_gradient[:, :, j]
        s_1 = 0.5 * a.T.dot(C).dot(a) - 0.5 * R.T.ravel().dot(C.ravel())
        b = C.dot(self.y_train_ - pi)
        s_3 = b - K.dot(R.dot(b))
        d_Z[j] = s_1 + s_2.T.dot(s_3)
    return (Z, d_Z)

def _unique_np(values, return_inverse=False, session=False):
    xp, _ = get_namespace(values)
    inverse, counts = (None, None)
    if return_inverse and session:
        uniques, _, inverse, counts = xp.unique_all(values)
    elif return_inverse:
        uniques, inverse = xp.unique_inverse(values)
    elif session:
        uniques, counts = xp.unique_counts(values)
    else:
        uniques = xp.unique_values(values)
    if uniques.size and is_scalar_nan(uniques[-1]):
        nan_idx = xp.searchsorted(uniques, xp.nan)
        uniques = uniques[:nan_idx + 1]
        if return_inverse:
            inverse[inverse > nan_idx] = nan_idx
        if session:
            counts[nan_idx] = xp.sum(counts[nan_idx:])
            counts = counts[:nan_idx + 1]
    ret = (uniques,)
    if return_inverse:
        ret += (inverse,)
    if session:
        ret += (counts,)
    return ret[0] if len(ret) == 1 else ret

