    for blk in self.blocks:
        mgr_locs = blk._mgr_locs
        values = blk.array_values._values_for_json()
        if values.ndim == 1:
            result[mgr_locs[0]] = values
        else:
            for i, loc in enumerate(mgr_locs):
                result[loc] = values[i]
    return result

@validate_params({'estimator': [HasMethods(['fit', 'predict']), HasMethods(['fit', 'predict_proba']), HasMethods(['fit', 'decision_function'])], 'X': ['array-like', 'sparse matrix'], 'features': ['array-like', Integral, str], 'sample_weight': ['array-like', None], 'categorical_features': ['array-like', None], 'feature_names': ['array-like', None], 'response_method': [StrOptions({'auto', 'predict_proba', 'decision_function'})], 'percentiles': [tuple], 'grid_resolution': [Interval(Integral, 1, None, closed='left')], 'method': [StrOptions({'auto', 'recursion', 'brute'})], 'kind': [StrOptions({'average', 'individual', 'both'})], 'custom_values': [dict, None]}, prefer_skip_nested_validation=True)
def partial_dependence(estimator, X, features, *, sample_weight=None, categorical_features=None, feature_names=None, response_method='auto', percentiles=(0.05, 0.95), grid_resolution=100, custom_values=None, method='auto', kind='average'):
    check_is_fitted(estimator)
    if not (is_classifier(estimator) or is_regressor(estimator)):
        raise ValueError("'estimator' must be a fitted regressor or classifier.")
    if is_classifier(estimator) and isinstance(estimator.classes_[0], np.ndarray):
        raise ValueError('Multiclass-multioutput estimators are not supported')
    if not (hasattr(X, '__array__') or sparse.issparse(X)):
        X = check_array(X, ensure_all_finite='allow-nan', dtype=object)
    if is_regressor(estimator) and response_method != 'auto':
        raise ValueError("The response_method parameter is ignored for regressors and must be 'auto'.")
    if kind != 'average':
        if method == 'recursion':
            raise ValueError("The 'recursion' method only applies when 'kind' is set to 'average'")
        method = 'brute'
    if method == 'recursion' and sample_weight is not None:
        raise ValueError("The 'recursion' method can only be applied when sample_weight is None.")
    if method == 'auto':
        if sample_weight is not None:
            method = 'brute'
        elif isinstance(estimator, BaseGradientBoosting) and estimator.init is None:
            method = 'recursion'
        elif isinstance(estimator, (BaseHistGradientBoosting, DecisionTreeRegressor, RandomForestRegressor)):
            method = 'recursion'
        else:
            method = 'brute'
    if method == 'recursion':
        if not isinstance(estimator, (BaseGradientBoosting, BaseHistGradientBoosting, DecisionTreeRegressor, RandomForestRegressor)):
            supported_classes_recursion = ('GradientBoostingClassifier', 'GradientBoostingRegressor', 'HistGradientBoostingClassifier', 'HistGradientBoostingRegressor', 'HistGradientBoostingRegressor', 'DecisionTreeRegressor', 'RandomForestRegressor')
            raise ValueError("Only the following estimators support the 'recursion' method: {}. Try using method='brute'.".format(', '.join(supported_classes_recursion)))
        if response_method == 'auto':
            response_method = 'decision_function'
        if response_method != 'decision_function':
            raise ValueError(f"With the 'recursion' method, the response_method must be 'decision_function'. Got {response_method}.")
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X)
    if _determine_key_type(features, accept_slice=False) == 'int':
        if np.any(np.less(features, 0)):
            raise ValueError(f'all features must be in [0, {X.shape[1] - 1}]')
    features_indices = np.asarray(_get_column_indices(X, features), dtype=np.intp, order='C').ravel()
    feature_names = _check_feature_names(X, feature_names)
    n_features = X.shape[1]
    if categorical_features is None:
        is_categorical = [False] * len(features_indices)
    else:
        categorical_features = np.asarray(categorical_features)
        if categorical_features.size == 0:
            raise ValueError('Passing an empty list (`[]`) to `categorical_features` is not supported. Use `None` instead to indicate that there are no categorical features.')
        if categorical_features.dtype.kind == 'b':
            if categorical_features.size != n_features:
                raise ValueError(f'When `categorical_features` is a boolean array-like, the array should be of shape (n_features,). Got {categorical_features.size} elements while `X` contains {n_features} features.')
            is_categorical = [categorical_features[idx] for idx in features_indices]
        elif categorical_features.dtype.kind in ('i', 'O', 'U'):
            categorical_features_idx = [_get_feature_index(cat, feature_names=feature_names) for cat in categorical_features]
            is_categorical = [idx in categorical_features_idx for idx in features_indices]
        else:
            raise ValueError(f'Expected `categorical_features` to be an array-like of boolean, integer, or string. Got {categorical_features.dtype} instead.')
    custom_values = custom_values or {}
    if isinstance(features, (str, int)):
        features = [features]
    for feature_idx, feature, is_cat in zip(features_indices, features, is_categorical):
        if is_cat:
            continue
        if _safe_indexing(X, feature_idx, axis=1).dtype.kind in 'iu':
            raise ValueError(f'The column {feature!r} contains integer data. Partial dependence plots are not supported for integer data: this can lead to implicit rounding with NumPy arrays or even errors with newer pandas versions. Please convert numerical features to floating point dtypes ahead of time to avoid problems.')
    X_subset = _safe_indexing(X, features_indices, axis=1)
    custom_values_for_X_subset = {index: custom_values.get(feature) for index, feature in enumerate(features) if feature in custom_values}
    grid, values = _grid_from_X(X_subset, percentiles, is_categorical, grid_resolution, custom_values_for_X_subset)
    if method == 'brute':
        averaged_predictions, predictions = _partial_dependence_brute(estimator, grid, features_indices, X, response_method, sample_weight)
        predictions = predictions.reshape(-1, X.shape[0], *[val.shape[0] for val in values])
    else:
        averaged_predictions = _partial_dependence_recursion(estimator, grid, features_indices)
    averaged_predictions = averaged_predictions.reshape(-1, *[val.shape[0] for val in values])
    pdp_results = Bunch(grid_values=values)
    if kind == 'average':
        pdp_results['average'] = averaged_predictions
    elif kind == 'individual':
        pdp_results['individual'] = predictions
    else:
        pdp_results['average'] = averaged_predictions
        pdp_results['individual'] = predictions
    return pdp_results

def _liac_arff_parser(gzip_file, output_arrays_type, openml_columns_info, feature_names_to_select, target_names_to_select, shape=None):

    def _io_to_generator(gzip_file):
        for line in gzip_file:
            yield line.decode('utf-8')
    stream = _io_to_generator(gzip_file)
    return_type = _arff.COO if output_arrays_type == 'sparse' else _arff.DENSE_GEN
    encode_nominal = not output_arrays_type == 'pandas'
    arff_container = _arff.load(stream, return_type=return_type, encode_nominal=encode_nominal)
    columns_to_select = feature_names_to_select + target_names_to_select
    categories = {name: cat for name, cat in arff_container['attributes'] if isinstance(cat, list) and name in columns_to_select}
    if output_arrays_type == 'pandas':
        pd = check_pandas_support('fetch_openml with as_frame=True')
        columns_info = OrderedDict(arff_container['attributes'])
        column_names = list(columns_info.keys())
        first_row = next(arff_container['data'])
        first_df = pd.DataFrame([first_row], columns=column_names, copy=False)
        row_bytes = first_df.memory_usage(deep=True).sum()
        chunksize = get_chunk_n_rows(row_bytes)
        columns_to_keep = [col for col in column_names if col in columns_to_select]
        dfs = [first_df[columns_to_keep]]
        for data in chunk_generator(arff_container['data'], chunksize):
            dfs.append(pd.DataFrame(data, columns=column_names, copy=False)[columns_to_keep])
        if len(dfs) >= 2:
            dfs[0] = dfs[0].astype(dfs[1].dtypes)
        frame = pd.concat(dfs, ignore_index=True)
        frame = pd_fillna(pd, frame)
        del dfs, first_df
        dtypes = {}
        for name in frame.columns:
            column_dtype = openml_columns_info[name]['data_type']
            if column_dtype.lower() == 'integer':
                dtypes[name] = 'Int64'
            elif column_dtype.lower() == 'nominal':
                dtypes[name] = 'category'
            else:
                dtypes[name] = frame.dtypes[name]
        frame = frame.astype(dtypes)
        X, y = _post_process_frame(frame, feature_names_to_select, target_names_to_select)
    else:
        arff_data = arff_container['data']
        feature_indices_to_select = [int(openml_columns_info[col_name]['index']) for col_name in feature_names_to_select]
        target_indices_to_select = [int(openml_columns_info[col_name]['index']) for col_name in target_names_to_select]
        if isinstance(arff_data, Generator):
            if shape is None:
                raise ValueError("shape must be provided when arr['data'] is a Generator")
            if shape[0] == -1:
                count = -1
            else:
                count = shape[0] * shape[1]
            data = np.fromiter(itertools.chain.from_iterable(arff_data), dtype='float64', count=count)
            data = data.reshape(*shape)
            X = data[:, feature_indices_to_select]
            y = data[:, target_indices_to_select]
        elif isinstance(arff_data, tuple):
            arff_data_X = _split_sparse_columns(arff_data, feature_indices_to_select)
            num_obs = max(arff_data[1]) + 1
            X_shape = (num_obs, len(feature_indices_to_select))
            X = sp.sparse.coo_array((arff_data_X[0], (arff_data_X[1], arff_data_X[2])), shape=X_shape, dtype=np.float64)
            X = _align_api_if_sparse(X.tocsr())
            y = _sparse_data_to_array(arff_data, target_indices_to_select)
        else:
            raise ValueError(f'Unexpected type for data obtained from arff: {type(arff_data)}')
        is_classification = {col_name in categories for col_name in target_names_to_select}
        if not is_classification:
            pass
        elif all(is_classification):
            y = np.hstack([np.take(np.asarray(categories.pop(col_name), dtype='O'), y[:, i:i + 1].astype(int, copy=False)) for i, col_name in enumerate(target_names_to_select)])
        elif any(is_classification):
            raise ValueError('Mix of nominal and non-nominal targets is not currently supported')
        if y.shape[1] == 1:
            y = y.reshape((-1,))
        elif y.shape[1] == 0:
            y = None
    if output_arrays_type == 'pandas':
        return None
    return (X, y, None, categories)

def get(self, url: _t.UriType, params: _t.ParamsType=None, **kwargs: Unpack[_t.GetKwargs]) -> Response:
    kwargs.setdefault('allow_redirects', True)
    return self.request('GET', url, params=params, **kwargs)

def split(self, X, y=None, groups=None):
    n_repeats = self.n_repeats
    rng = check_random_state(self.random_state)
    for idx in range(n_repeats):
        cv = self.cv(random_state=rng, shuffle=True, **self.cvargs)
        for train_index, test_index in cv.split(X, y, groups):
            yield (train_index, test_index)

@final
def fillna(self, value: Hashable | Mapping | Series | DataFrame, *, axis: Axis | None=None, inplace: bool=False, limit: int | None=None) -> Self:
    inplace = validate_bool_kwarg(inplace, 'inplace')
    if inplace:
        if not CHAINED_WARNING_DISABLED:
            if sys.getrefcount(self) <= REF_COUNT_METHOD and (not common.is_local_in_caller_frame(self)):
                warnings.warn(_chained_assignment_method_msg, ChainedAssignmentError, stacklevel=2)
    if isinstance(value, (list, tuple)):
        raise TypeError(f'"value" parameter must be a scalar or dict, but you passed a "{type(value).__name__}"')
    if axis is None:
        axis = 0
    axis = self._get_axis_number(axis)
    if self.ndim == 1:
        if isinstance(value, (dict, ABCSeries)):
            if not len(value):
                return None
            from pandas import Series
            value = Series(value)
            value = value.reindex(self.index)
            value = value._values
        elif not is_list_like(value):
            pass
        else:
            raise TypeError(f'"value" parameter must be a scalar, dict or Series, but you passed a "{type(value).__name__}"')
        new_data = self._mgr.fillna(value=value, limit=limit, inplace=inplace)
    elif isinstance(value, (dict, ABCSeries)):
        result = self if inplace else self.copy(deep=False)
        if axis == 1:
            unique_dtypes = self._mgr.get_unique_dtypes()
            if len(unique_dtypes) > 1:
                raise ValueError(f'All columns must have the same dtype, but got dtypes: {list(unique_dtypes)}')
            if not can_hold_element(result.iloc[:, 0], value):
                frame_dtype = unique_dtypes.item()
                raise ValueError(f'{value} not a suitable type to fill into {frame_dtype}')
            result = result.T.fillna(value=value).T
            if inplace:
                self._update_inplace(result)
                result = self
        else:
            for k, v in value.items():
                if k not in result:
                    continue
                res_k = result[k].fillna(v, limit=limit)
                if not inplace:
                    result[k] = res_k
                elif isinstance(res_k, ABCSeries):
                    if res_k.dtype == result[k].dtype:
                        result.loc[:, k] = res_k
                    else:
                        result[k] = res_k
                else:
                    locs = result.columns.get_loc(k)
                    if isinstance(locs, slice):
                        locs = range(self.shape[1])[locs]
                    elif isinstance(locs, np.ndarray) and locs.dtype.kind == 'b':
                        locs = locs.nonzero()[0]
                    elif not (isinstance(locs, np.ndarray) and locs.dtype.kind == 'i'):
                        raise NotImplementedError('Unexpected get_loc result, please report a bug at https://github.com/pandas-dev/pandas')
                    for i, loc in enumerate(locs):
                        res_loc = res_k.iloc[:, i]
                        target = self.iloc[:, loc]
                        if res_loc.dtype == target.dtype:
                            result.iloc[:, loc] = res_loc
                        else:
                            result.isetitem(loc, res_loc)
        return result
    elif not is_list_like(value):
        if axis == 1:
            result = self.T.fillna(value=value, limit=limit).T
            new_data = result._mgr
        else:
            new_data = self._mgr.fillna(value=value, limit=limit, inplace=inplace)
    elif isinstance(value, ABCDataFrame) and self.ndim == 2:
        new_data = self.where(self.notna(), value)._mgr
    else:
        raise ValueError(f'invalid fill value with a {type(value)}')
    result = self._constructor_from_mgr(new_data, axes=new_data.axes)
    if inplace:
        self._update_inplace(result)
        return self
    else:
        return result.__finalize__(self, method='fillna')

def get_op_from_name(op_name: str) -> Callable:
    short_opname = op_name.strip('_')
    try:
        op = getattr(operator, short_opname)
    except AttributeError:
        rop = getattr(operator, short_opname[1:])
        op = lambda x, y: rop(y, x)
    return op

def _hist_bin_auto(x, range):
    fd_bw = _hist_bin_fd(x, range)
    sturges_bw = _hist_bin_sturges(x, range)
    sqrt_bw = _hist_bin_sqrt(x, range)
    fd_bw_corrected = max(fd_bw, sqrt_bw / 2)
    return min(fd_bw_corrected, sturges_bw)

def explode(self, ignore_index: bool=False) -> Series:
    if isinstance(self.dtype, ExtensionDtype):
        values, counts = self._values._explode()
    elif len(self) and is_object_dtype(self.dtype):
        values, counts = reshape.explode(np.asarray(self._values))
    else:
        result = self.copy()
        return result.reset_index(drop=True) if ignore_index else result
    if ignore_index:
        index: Index = default_index(len(values))
    else:
        index = self.index.repeat(counts)
    return self._constructor(values, index=index, name=self.name, copy=False)

@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y):
    self._fit(X, y)
    classes_ = self.classes_
    _y = self._y
    if not self.outputs_2d_:
        _y = self._y.reshape((-1, 1))
        classes_ = [self.classes_]
    if self.outlier_label is None:
        outlier_label_ = None
    elif self.outlier_label == 'most_frequent':
        outlier_label_ = []
        for k, classes_k in enumerate(classes_):
            label_count = np.bincount(_y[:, k])
            outlier_label_.append(classes_k[label_count.argmax()])
    else:
        if _is_arraylike(self.outlier_label) and (not isinstance(self.outlier_label, str)):
            if len(self.outlier_label) != len(classes_):
                raise ValueError('The length of outlier_label: {} is inconsistent with the output length: {}'.format(self.outlier_label, len(classes_)))
            outlier_label_ = self.outlier_label
        else:
            outlier_label_ = [self.outlier_label] * len(classes_)
        for classes, label in zip(classes_, outlier_label_):
            if _is_arraylike(label) and (not isinstance(label, str)):
                raise TypeError('The outlier_label of classes {} is supposed to be a scalar, got {}.'.format(classes, label))
            if np.append(classes, label).dtype != classes.dtype:
                raise TypeError('The dtype of outlier_label {} is inconsistent with classes {} in y.'.format(label, classes))
    self.outlier_label_ = outlier_label_
    return self

def _from_ctypes_scalar(t):
    if getattr(t, '__ctype_be__', None) is t:
        return None
    elif getattr(t, '__ctype_le__', None) is t:
        return np.dtype('<' + t._type_)
    else:
        return np.dtype(t._type_)

def get_block_type(dtype: DtypeObj) -> type[Block]:
    if isinstance(dtype, DatetimeTZDtype):
        return DatetimeLikeBlock
    elif isinstance(dtype, PeriodDtype):
        return NDArrayBackedExtensionBlock
    elif isinstance(dtype, ExtensionDtype):
        return ExtensionBlock
    kind = dtype.kind
    if kind in 'Mm':
        return DatetimeLikeBlock
    return NumpyBlock

def __call__(self, item):

    @wraps(item)
    def new_func(*args, **kwargs):
        with self:
            return item(*args, **kwargs)
    return new_func

def __pow__(self, other):
    if self._delegate_binop(other):
        return NotImplemented
    return power(self, other)

def _nanquantile_ureduce_func(a: np.ndarray, q: np.ndarray, weights: np.ndarray, index: int | None=None, out=None, overwrite_input: bool=False, method='linear', weak_q=False):
    if index is None or a.ndim == 1:
        part = a.ravel()
        wgt = None if weights is None else weights.ravel()
        result = _nanquantile_1d(part, q, overwrite_input, method, weights=wgt, weak_q=weak_q)
    elif weights is None:
        result = np.apply_along_axis(_nanquantile_1d, index, a, q, overwrite_input, method, weights, weak_q)
        if q.ndim != 0:
            from_ax = [index + i for i in range(q.ndim)]
            result = np.moveaxis(result, from_ax, list(range(q.ndim)))
    else:
        a = np.moveaxis(a, index, -1)
        if weights is not None:
            weights = np.moveaxis(weights, index, -1)
        if out is not None:
            result = out
        else:
            result = np.empty_like(a, shape=q.shape + a.shape[:-1])
        for ii in np.ndindex(a.shape[:-1]):
            result[(...,) + ii] = _nanquantile_1d(a[ii], q, weights=weights[ii], overwrite_input=overwrite_input, method=method, weak_q=weak_q)
        return result
    if out is not None:
        out[...] = result
    return result

def _check_targets(y_true, y_pred, sample_weight=None):
    xp, _ = get_namespace(y_true, y_pred, sample_weight)
    check_consistent_length(y_true, y_pred, sample_weight)
    type_true = type_of_target(y_true, input_name='y_true')
    type_pred = type_of_target(y_pred, input_name='y_pred')
    for array in [y_true, y_pred]:
        if _num_samples(array) < 1:
            raise ValueError('Found empty input array (e.g., `y_true` or `y_pred`) while a minimum of 1 sample is required.')
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, y_true, force_float_dtype=False)
    y_type = {type_true, type_pred}
    if y_type == {'binary', 'multiclass'}:
        y_type = {'multiclass'}
    if len(y_type) > 1:
        raise ValueError("Classification metrics can't handle a mix of {0} and {1} targets".format(type_true, type_pred))
    y_type = y_type.pop()
    if y_type not in ['binary', 'multiclass', 'multilabel-indicator']:
        raise ValueError('{0} is not supported'.format(y_type))
    if y_type in ['binary', 'multiclass']:
        try:
            y_true = column_or_1d(y_true, input_name='y_true')
            y_pred = column_or_1d(y_pred, input_name='y_pred')
        except TypeError as e:
            if 'Sparse data was passed' in str(e):
                raise TypeError('Sparse input is only supported when targets are of multilabel type') from e
            else:
                raise
    unique_labels_ = unique_labels(y_true, y_pred, ys_types={y_type})
    if y_type == 'binary':
        if unique_labels_.shape[0] > 2:
            y_type = 'multiclass'
    xp, _ = get_namespace(y_true, y_pred)
    if y_type.startswith('multilabel'):
        if _is_numpy_namespace(xp):
            y_true = _align_api_if_sparse(csr_array(y_true))
            y_pred = _align_api_if_sparse(csr_array(y_pred))
        y_type = 'multilabel-indicator'
    return (y_type, unique_labels_, y_true, y_pred, sample_weight)

def _levels_to_axis(ss, levels: tuple[int] | list[int], valid_ilocs: npt.NDArray[np.intp], sort_labels: bool=False) -> tuple[npt.NDArray[np.intp], list[IndexLabel]]:
    if sort_labels and len(levels) == 1:
        ax_coords = ss.index.codes[levels[0]][valid_ilocs]
        ax_labels = ss.index.levels[levels[0]]
    else:
        levels_values = lib.fast_zip([ss.index.get_level_values(lvl).to_numpy() for lvl in levels])
        codes, ax_labels = factorize(levels_values, sort=sort_labels)
        ax_coords = codes[valid_ilocs]
    ax_labels = ax_labels.tolist()
    return (ax_coords, ax_labels)

def fit_intercept_only(self, cache, sample_weight=None):
    if sample_weight is None:
        median = np.percentile(cache, 50, axis=0)
    else:
        median = _weighted_percentile(cache, sample_weight, 50)
    diff = cache - median
    term = np.sign(diff) * np.minimum(self.closs.delta, np.abs(diff))
    return median + np.average(term, weights=sample_weight)

@array_function_dispatch(_nonzero_dispatcher)
def nonzero(a):
    return _wrapfunc(a, 'nonzero')

def get_handle(path_or_buf: FilePath | BaseBuffer, mode: str, *, encoding: str | None=None, compression: CompressionOptions | None=None, memory_map: bool=False, is_text: bool=True, errors: str | None=None, storage_options: StorageOptions | None=None) -> IOHandles[str] | IOHandles[bytes]:
    encoding = encoding or 'utf-8'
    errors = errors or 'strict'
    if _is_binary_mode(path_or_buf, mode) and 'b' not in mode:
        mode += 'b'
    codecs.lookup(encoding)
    if isinstance(errors, str):
        codecs.lookup_error(errors)
    ioargs = _get_filepath_or_buffer(path_or_buf, encoding=encoding, compression=compression, mode=mode, storage_options=storage_options)
    handle = ioargs.filepath_or_buffer
    handles: list[BaseBuffer]
    handle, memory_map, handles = _maybe_memory_map(handle, memory_map)
    is_path = isinstance(handle, str)
    compression_args = dict(ioargs.compression)
    compression = compression_args.pop('method')
    if 'r' not in mode and is_path:
        check_parent_directory(str(handle))
    if compression:
        if compression != 'zstd':
            ioargs.mode = ioargs.mode.replace('t', '')
        elif compression == 'zstd' and 'b' not in ioargs.mode:
            ioargs.mode += 'b'
        if compression == 'gzip':
            if isinstance(handle, str):
                handle = gzip.GzipFile(filename=handle, mode=ioargs.mode, **compression_args)
            else:
                handle = gzip.GzipFile(fileobj=handle, mode=ioargs.mode, **compression_args)
        elif compression == 'bz2':
