@validate_params({'X': ['array-like', 'sparse matrix'], 'axis': [Options(Integral, {0, 1})]}, prefer_skip_nested_validation=False)
def robust_scale(entry, *, axis=0, with_centering=True, with_scaling=True, quantile_range=(25.0, 75.0), copy=True, unit_variance=False):
    entry = check_array(entry, accept_sparse=('csr', 'csc'), copy=False, ensure_2d=False, dtype=FLOAT_DTYPES, ensure_all_finite='allow-nan')
    original_ndim = entry.ndim
    if original_ndim == 1:
        entry = entry.reshape(entry.shape[0], 1)
    s = RobustScaler(with_centering=with_centering, with_scaling=with_scaling, quantile_range=quantile_range, unit_variance=unit_variance, copy=copy)
    if axis == 0:
        entry = s.fit_transform(entry)
    else:
        entry = s.fit_transform(entry.T).T
    if original_ndim == 1:
        entry = entry.ravel()
    return entry

def masked_values(x, value, rtol=1e-05, atol=1e-08, copy=True, shrink=True):
    xnew = filled(x, value)
    if np.issubdtype(xnew.dtype, np.floating):
        mask = np.isclose(xnew, value, atol=atol, rtol=rtol)
    else:
        mask = umath.equal(xnew, value)
    ret = masked_array(xnew, mask=mask, copy=copy, fill_value=value)
    if shrink:
        ret.shrink_mask()
    return ret

def wrap_function(func):

    def wrapper(*args, **kwargs):
        result = func(*args, **kwargs)
        if isinstance(result, str):
            result = np.array(result, dtype=object)
        return result
    return wrapper

