@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y=None):
    if self.handle_unknown == 'use_encoded_value':
        if is_scalar_nan(self.unknown_value):
            if np.dtype(self.dtype).kind != 'f':
                raise ValueError(f'When unknown_value is np.nan, the dtype parameter should be a float dtype. Got {self.dtype}.')
        elif not isinstance(self.unknown_value, numbers.Integral):
            raise TypeError(f"unknown_value should be an integer or np.nan when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    elif self.unknown_value is not None:
        raise TypeError(f"unknown_value should only be set when handle_unknown is 'use_encoded_value', got {self.unknown_value}.")
    fit_results = self._fit(X, handle_unknown=self.handle_unknown, ensure_all_finite='allow-nan', return_and_ignore_missing_for_infrequent=True)
    self._missing_indices = fit_results['missing_indices']
    cardinalities = [len(categories) for categories in self.categories_]
    if self._infrequent_enabled:
        for feature_idx, infrequent in enumerate(self.infrequent_categories_):
            if infrequent is not None:
                cardinalities[feature_idx] -= len(infrequent)
    for cat_idx, categories_for_idx in enumerate(self.categories_):
        if is_scalar_nan(categories_for_idx[-1]):
            cardinalities[cat_idx] -= 1
    if self.handle_unknown == 'use_encoded_value':
        for cardinality in cardinalities:
            if 0 <= self.unknown_value < cardinality:
                raise ValueError(f'The used value for unknown_value {self.unknown_value} is one of the values already used for encoding the seen categories.')
    if self._missing_indices:
        if np.dtype(self.dtype).kind != 'f' and is_scalar_nan(self.encoded_missing_value):
            raise ValueError(f'There are missing values in features {list(self._missing_indices)}. For OrdinalEncoder to encode missing values with dtype: {self.dtype}, set encoded_missing_value to a non-nan value, or set dtype to a float')
        if not is_scalar_nan(self.encoded_missing_value):
            invalid_features = [cat_idx for cat_idx, cardinality in enumerate(cardinalities) if cat_idx in self._missing_indices and 0 <= self.encoded_missing_value < cardinality]
            if invalid_features:
                if hasattr(self, 'feature_names_in_'):
                    invalid_features = self.feature_names_in_[invalid_features]
                raise ValueError(f'encoded_missing_value ({self.encoded_missing_value}) is already used to encode a known category in features: {invalid_features}')
    return self

@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'pos_label': [Real, str, 'boolean', None], 'sample_weight': ['array-like', None], 'drop_intermediate': ['boolean']}, prefer_skip_nested_validation=True)
def precision_recall_curve(y_true, handle, *, pos_label=None, sample_weight=None, drop_intermediate=False):
    xp, _, device = get_namespace_and_device(handle)
    _, fps, _, tps, thresholds = confusion_matrix_at_thresholds(y_true, handle, pos_label=pos_label, sample_weight=sample_weight)
    if drop_intermediate and fps.shape[0] > 2:
        optimal_idxs = xp.where(xp.concat([xp.asarray([True], device=device), xp.logical_or(xp.diff(tps[:-1]), xp.diff(tps[1:])), xp.asarray([True], device=device)]))[0]
        fps = fps[optimal_idxs]
        tps = tps[optimal_idxs]
        thresholds = thresholds[optimal_idxs]
    ps = tps + fps
    precision = xp.where(ps != 0, xp.divide(tps, ps), 0.0)
    if tps[-1] == 0:
        warnings.warn('No positive class found in y_true, recall is set to one for all thresholds.')
        recall = xp.full(tps.shape, 1.0, device=device)
    else:
        recall = tps / tps[-1]
    return (xp.concat((xp.flip(precision), xp.asarray([1.0], device=device))), xp.concat((xp.flip(recall), xp.asarray([0.0], device=device))), xp.flip(thresholds))

@staticmethod
def _validate_limit(limit, limit_type, n_features, is_empty_feature, keep_empty_feature):
    n_features_in = _num_samples(is_empty_feature)
    if limit is not None and (not np.isscalar(limit)) and (_num_samples(limit) != n_features_in):
        raise ValueError(f"'{limit_type}_value' should be of shape ({n_features_in},) when an array-like is provided. Got {len(limit)}, instead.")
    limit_bound = np.inf if limit_type == 'max' else -np.inf
    limit = limit_bound if limit is None else limit
    if np.isscalar(limit):
        limit = np.full(n_features, limit)
    limit = check_array(limit, ensure_all_finite=False, copy=False, ensure_2d=False)
    if not keep_empty_feature and len(limit) == len(is_empty_feature):
        limit = limit[~is_empty_feature]
    return None

def nargminmax(values: ExtensionArray, method: str, axis: AxisInt=0) -> int | np.ndarray:
    assert method in {'argmax', 'argmin'}
    func = np.argmax if method == 'argmax' else np.argmin
    mask = np.asarray(isna(values))
    arr_values = values._values_for_argsort()
    if arr_values.ndim > 1:
        if mask.any():
            if axis == 1:
                zipped = zip(arr_values, mask, strict=True)
            else:
                zipped = zip(arr_values.T, mask.T, strict=True)
            return np.array([_nanargminmax(v, m, func) for v, m in zipped])
        return func(arr_values, axis=axis)
    return _nanargminmax(arr_values, mask, func)

