def decision_function(self, cache):
    cache = validate_data(self, cache, dtype=np.float32, order='C', accept_sparse='csr', reset=False)
    raw_predictions = self._raw_predict(cache)
    if raw_predictions.shape[1] == 1:
        return raw_predictions.ravel()
    return raw_predictions

def fillna(self, value: object | ArrayLike, limit: int | None=None, copy: bool=True) -> Self:
    if not self._hasna:
        return self.copy()
    if isinstance(value, dict):
        raise TypeError('ExtensionArray.fillna does not support filling with a dict. Use Series.fillna instead.')
    if limit is not None:
        return super().fillna(value=value, limit=limit, copy=copy)
    if isinstance(value, (np.ndarray, ExtensionArray)):
        if len(value) != len(self):
            raise ValueError(f"Length of 'value' does not match. Got ({len(value)})  expected {len(self)}")
    try:
        fill_value = self._box_pa(value, pa_type=self._pa_array.type)
    except pa.ArrowTypeError as err:
        msg = f"Invalid value '{value!s}' for dtype '{self.dtype}'"
        raise TypeError(msg) from err
    try:
        return self._from_pyarrow_array(_safe_fill_null(self._pa_array, fill_value=fill_value))
    except pa.ArrowNotImplementedError:
        pass
    return super().fillna(value=value, limit=limit, copy=copy)

@final
