    if kind == 'bool':
        return {'bool': bool}
    if kind == 'signed integer':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64)}
    if kind == 'unsigned integer':
        return {'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'integral':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64)}
    if kind == 'real floating':
        return {'float32': dtype(float32), 'float64': dtype(float64)}
    if kind == 'complex floating':
        return {'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if kind == 'numeric':
        return {'int8': dtype(int8), 'int16': dtype(int16), 'int32': dtype(int32), 'int64': dtype(int64), 'uint8': dtype(uint8), 'uint16': dtype(uint16), 'uint32': dtype(uint32), 'uint64': dtype(uint64), 'float32': dtype(float32), 'float64': dtype(float64), 'complex64': dtype(complex64), 'complex128': dtype(complex128)}
    if isinstance(kind, tuple):
        res = {}
        for k in kind:
