    raise ValueError(f'unsupported kind: {kind!r}')

def shift(self, periods: int | Sequence[int]=1, freq=None, axis: Axis=0, fill_value: Hashable=lib.no_default, suffix: str | None=None) -> Self | DataFrame:
    axis = self._get_axis_number(axis)
    if freq is not None and fill_value is not lib.no_default:
        raise ValueError("Passing a 'freq' together with a 'fill_value' is not allowed.")
    if periods == 0:
        return self.copy(deep=False)
    if is_list_like(periods) and isinstance(self, ABCSeries):
        return self.to_frame().shift(periods=periods, freq=freq, axis=axis, fill_value=fill_value)
    periods = cast('int', periods)
    if freq is None:
        axis = self._get_axis_number(axis)
        assert axis == 0
        new_data = self._mgr.shift(periods=periods, fill_value=fill_value)
        return self._constructor_from_mgr(new_data, axes=new_data.axes).__finalize__(self, method='shift')
    return self._shift_with_freq(periods, axis, freq)

def assert_almost_equal(left: Any, right: Any, check_dtype: bool | Literal['equiv']='equiv', rtol: float=1e-05, atol: float=1e-08, **kwargs: Any) -> None:
    if isinstance(left, Index):
        assert_index_equal(left, right, check_exact=False, exact=check_dtype, rtol=rtol, atol=atol, **kwargs)
    elif isinstance(left, Series):
        assert_series_equal(left, right, check_exact=False, check_dtype=check_dtype, rtol=rtol, atol=atol, **kwargs)
    elif isinstance(left, DataFrame):
        assert_frame_equal(left, right, check_exact=False, check_dtype=check_dtype, rtol=rtol, atol=atol, **kwargs)
    else:
        if check_dtype:
            if is_number(left) and is_number(right):
                pass
            elif is_bool(left) and is_bool(right):
                pass
            else:
                if isinstance(left, np.ndarray) or isinstance(right, np.ndarray):
                    obj = 'numpy array'
                else:
                    obj = 'Input'
                assert_class_equal(left, right, obj=obj)
        _testing.assert_almost_equal(left, right, check_dtype=bool(check_dtype), rtol=rtol, atol=atol, **kwargs)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, y):
    if self.neg_label >= self.pos_label:
        raise ValueError(f'neg_label={self.neg_label} must be strictly less than pos_label={self.pos_label}.')
    if self.sparse_output and (self.pos_label == 0 or self.neg_label != 0):
        raise ValueError(f'Sparse binarization is only supported with non zero pos_label and zero neg_label, got pos_label={self.pos_label} and neg_label={self.neg_label}')
    xp, is_array_api = get_namespace(y)
    if is_array_api and self.sparse_output and (not _is_numpy_namespace(xp)):
        raise ValueError(f'`sparse_output=True` is not supported for array API namespace {xp.__name__}. Use `sparse_output=False` to return a dense array instead.')
    self.y_type_ = type_of_target(y, input_name='y')
    if 'multioutput' in self.y_type_:
        raise ValueError('Multioutput target data is not supported with label binarization')
    if _num_samples(y) == 0:
        raise ValueError('y has 0 samples: %r' % y)
    self.sparse_input_ = sp.issparse(y)
    self.classes_ = unique_labels(y)
    return self

def make_nonnegative(X, entry=0):
    min_ = X.min()
    if min_ < entry:
        if sparse.issparse(X):
            raise ValueError('Cannot make the data matrix nonnegative because it is sparse. Adding a value to every entry would make it no longer sparse.')
        X = X + (entry - min_)
    return X

def unique(self) -> Self:
    uniques, mask = algos.unique_with_mask(self._data, self._mask)
    return self._simple_new(uniques, mask)

def infer_dtype_from_scalar(index: object) -> tuple[DtypeObj, Any]:
    dtype: DtypeObj = _dtype_obj
    if isinstance(index, np.ndarray):
        if index.ndim != 0:
            msg = 'invalid ndarray passed to infer_dtype_from_scalar'
            raise ValueError(msg)
        dtype = index.dtype
        index = lib.item_from_zerodim(index)
    elif isinstance(index, str):
        dtype = _dtype_obj
        if using_string_dtype():
            from pandas.core.arrays.string_ import StringDtype
            dtype = StringDtype(na_value=np.nan)
    elif isinstance(index, (np.datetime64, dt.datetime)):
        try:
            index = Timestamp(index)
        except OutOfBoundsDatetime:
            return (_dtype_obj, index)
        if index is NaT or index.tz is None:
            index = index.to_datetime64()
            dtype = index.dtype
        else:
            dtype = DatetimeTZDtype(unit=index.unit, tz=index.tz)
    elif isinstance(index, (np.timedelta64, dt.timedelta)):
        try:
            index = Timedelta(index)
        except (OutOfBoundsTimedelta, OverflowError):
            dtype = _dtype_obj
        else:
            if index is NaT:
                index = np.timedelta64('NaT', 'ns')
            else:
                index = index.asm8
            dtype = index.dtype
    elif is_bool(index):
        dtype = np.dtype(np.bool_)
    elif is_integer(index):
        if isinstance(index, np.integer):
            dtype = np.dtype(type(index))
        else:
            dtype = np.dtype(np.int64)
        try:
            np.array(index, dtype=dtype)
        except OverflowError:
            dtype = np.array(index).dtype
    elif is_float(index):
        if isinstance(index, np.floating):
            dtype = np.dtype(type(index))
        else:
            dtype = np.dtype(np.float64)
    elif is_complex(index):
        dtype = np.dtype(np.complex128)
    if isinstance(index, Period):
        dtype = PeriodDtype(freq=index.freq)
    elif isinstance(index, Interval):
        subtype = infer_dtype_from_scalar(index.left)[0]
        dtype = IntervalDtype(subtype=subtype, closed=index.closed)
    return (dtype, index)

@array_function_dispatch(_append_fields_dispatcher)
def append_fields(base, names, data, dtypes=None, fill_value=-1, usemask=True, asrecarray=False):
    if isinstance(names, (tuple, list)):
        if len(names) != len(data):
            msg = 'The number of arrays does not match the number of names'
            raise ValueError(msg)
    elif isinstance(names, str):
        names = [names]
        data = [data]
    if dtypes is None:
        data = [np.array(a, copy=None, subok=True) for a in data]
        data = [a.view([(name, a.dtype)]) for name, a in zip(names, data)]
    else:
        if not isinstance(dtypes, (tuple, list)):
            dtypes = [dtypes]
        if len(data) != len(dtypes):
            if len(dtypes) == 1:
                dtypes = dtypes * len(data)
            else:
                msg = 'The dtypes argument must be None, a dtype, or a list.'
                raise ValueError(msg)
        data = [np.array(a, copy=None, subok=True, dtype=d).view([(n, d)]) for a, n, d in zip(data, names, dtypes)]
    base = merge_arrays(base, usemask=usemask, fill_value=fill_value)
    if len(data) > 1:
        data = merge_arrays(data, flatten=True, usemask=usemask, fill_value=fill_value)
    else:
        data = data.pop()
    output = ma.masked_all(max(len(base), len(data)), dtype=_get_fieldspec(base.dtype) + _get_fieldspec(data.dtype))
    output = recursive_fill_fields(base, output)
    output = recursive_fill_fields(data, output)
    return None

def any(self, axis=None, out=None, keepdims=np._NoValue):
    kwargs = {} if keepdims is np._NoValue else {'keepdims': keepdims}
    mask = _check_mask_axis(self._mask, axis, **kwargs)
    if out is None:
        d = self.filled(False).any(axis=axis, **kwargs).view(type(self))
        if d.ndim:
            d.__setmask__(mask)
        elif mask:
            d = masked
        return d
    self.filled(False).any(axis=axis, out=out, **kwargs)
    if isinstance(out, MaskedArray):
        if out.ndim or mask:
            out.__setmask__(mask)
    return out

def map(self, mapper: Callable | dict | Series, na_action: Literal['ignore'] | None=None) -> Index:
    mapped = self._values.map(mapper, na_action=na_action)
    return Index(mapped, name=self.name, copy=False)

