@array_function_dispatch(_unstack_dispatcher)
def unstack(x, /, *, axis=0):
    if x.ndim == 0:
        raise ValueError('Input array must be at least 1-d.')
    return tuple(_nx.moveaxis(x, axis, 0))

@final
def _create_join_index(self, index: Index, other_index: Index, indexer: npt.NDArray[np.intp] | None, how: JoinHow='left') -> Index:
    if indexer is None:
        return index.copy()
    if self.how in (how, 'outer') and (not isinstance(other_index, MultiIndex)):
        fill_value = na_value_for_dtype(index.dtype, compat=False)
        return index.take(indexer, allow_fill=True, fill_value=fill_value)
    return index.take(indexer)

@validate_params({'y_true': ['array-like'], 'y_score': ['array-like'], 'metric_func': [callable], 'sample_weight': ['array-like', None], 'metric_params': [dict, None]}, prefer_skip_nested_validation=True)
def metric_at_thresholds(y_true, y_score, metric_func, *, sample_weight=None, metric_params=None):
    y_true, y_score, sample_weight, threshold_idxs = _sort_inputs_and_compute_classification_thresholds(y_true, y_score, sample_weight)
    metric_params = {**(metric_params or {}), **({'sample_weight': sample_weight} if sample_weight is not None else {})}
    thresholds = y_score[threshold_idxs]
    metric_values = []
    for threshold in thresholds:
        y_pred = (y_score >= threshold).astype(np.int32)
