def _validate_curve_kwargs(n_curves, name, legend_metric, legend_metric_name, curve_kwargs, default_curve_kwargs=None, default_multi_curve_kwargs=None, removed_version='1.9', **kwargs):
    if curve_kwargs and kwargs:
        raise ValueError(f'Cannot provide both `curve_kwargs` and `kwargs`. `**kwargs` is deprecated and will be removed in {removed_version}. Pass all matplotlib arguments to `curve_kwargs` as a dictionary.')
    if kwargs:
        warnings.warn(f'`**kwargs` is deprecated and will be removed in {removed_version}. Pass all matplotlib arguments to `curve_kwargs` as a dictionary instead.', FutureWarning)
        curve_kwargs = kwargs
    if isinstance(curve_kwargs, list) and len(curve_kwargs) != n_curves:
        raise ValueError(f'`curve_kwargs` must be None, a dictionary or a list of length {n_curves}. Got: {curve_kwargs}.')
    if isinstance(name, list) and len(name) != 1 and (not isinstance(curve_kwargs, list)):
        raise ValueError(f'To avoid labeling individual curves that have the same appearance, `curve_kwargs` should be a list of {n_curves} dictionaries. Alternatively, set `name` to `None` or a single string to label a single legend entry for all curves.')
    if isinstance(name, str):
        name = [name]
    if isinstance(name, list) and len(name) == 1:
        name = name * n_curves
    name = [None] * n_curves if name is None else name
    if isinstance(curve_kwargs, Mapping):
        curve_kwargs = [curve_kwargs] * n_curves
    elif curve_kwargs is None:
        curve_kwargs = [{}] * n_curves
    if default_curve_kwargs is None:
        default_curve_kwargs = {}
    if default_multi_curve_kwargs is None:
        default_multi_curve_kwargs = {}
    if n_curves > 1:
        default_curve_kwargs.update(default_multi_curve_kwargs)
    labels = []
    if 'mean' in legend_metric:
        label_aggregate = _BinaryClassifierCurveDisplayMixin._get_legend_label(legend_metric['mean'], name[0], legend_metric_name)
        if legend_metric['std'] is not None:
            if name[0] is not None:
                label_aggregate = label_aggregate[:-1] + f" +/- {legend_metric['std']:0.2f})"
            else:
                label_aggregate = label_aggregate + f" +/- {legend_metric['std']:0.2f}"
        labels.extend([label_aggregate] + [None] * (n_curves - 1))
    else:
        for curve_legend_metric, curve_name in zip(legend_metric['metric'], name):
            labels.append(_BinaryClassifierCurveDisplayMixin._get_legend_label(curve_legend_metric, curve_name, legend_metric_name))
    curve_kwargs_ = [_validate_style_kwargs({'label': label, **default_curve_kwargs}, curve_kwargs[fold_idx]) for fold_idx, label in enumerate(labels)]
