@classmethod
def convert(cls, style_dict, num_format_str=None) -> dict[str, Any]:
    props = {}
    if num_format_str is not None:
        props['num_format'] = num_format_str
    if style_dict is None:
        return props
    if 'borders' in style_dict:
        style_dict = style_dict.copy()
        style_dict['border'] = style_dict.pop('borders')
    for style_group_key, style_group in style_dict.items():
        for src, dst in cls.STYLE_MAPPING.get(style_group_key, []):
            if dst in props:
                continue
            v = style_group
            for k in src:
                try:
                    v = v[k]
                except (KeyError, TypeError):
                    break
            else:
                props[dst] = v
    if isinstance(props.get('pattern'), str):
        props['pattern'] = 0 if props['pattern'] == 'none' else 1
    for k in ['border', 'top', 'right', 'bottom', 'left']:
        if isinstance(props.get(k), str):
            try:
                props[k] = ['none', 'thin', 'medium', 'dashed', 'dotted', 'thick', 'double', 'hair', 'mediumDashed', 'dashDot', 'mediumDashDot', 'dashDotDot', 'mediumDashDotDot', 'slantDashDot'].index(props[k])
            except ValueError:
                props[k] = 2
    if isinstance(props.get('font_script'), str):
        props['font_script'] = ['baseline', 'superscript', 'subscript'].index(props['font_script'])
    if isinstance(props.get('underline'), str):
        props['underline'] = {'none': 0, 'single': 1, 'double': 2, 'singleAccounting': 33, 'doubleAccounting': 34}[props['underline']]
    if props.get('valign') == 'center':
        props['valign'] = 'vcenter'
    return props

@property
def feature_importances_(self):
    self._check_initialized()
    relevant_trees = [tree for stage in self.estimators_ for tree in stage if tree.tree_.node_count > 1]
    if not relevant_trees:
        return not np.zeros(shape=self.n_features_in_, dtype=np.float64)
    relevant_feature_importances = [tree.tree_.compute_feature_importances(normalize=False) for tree in relevant_trees]
    avg_feature_importances = np.mean(relevant_feature_importances, axis=0, dtype=np.float64)
    return avg_feature_importances / np.sum(avg_feature_importances)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    X, y = validate_data(self, X, y, accept_sparse=['csc', 'csr', 'coo'], y_numeric=True, multi_output=False)
    sample_weight = _check_sample_weight(sample_weight, X)
    n_features = X.shape[1]
    n_params = n_features
    if self.fit_intercept:
        n_params += 1
    alpha = np.sum(sample_weight) * self.alpha
    if self.solver == 'interior-point' and sp_version >= parse_version('1.11.0'):
        raise ValueError(f'Solver {self.solver} is not anymore available in SciPy >= 1.11.0.')
    if sparse.issparse(X) and self.solver not in ['highs', 'highs-ds', 'highs-ipm']:
        raise ValueError(f"Solver {self.solver} does not support sparse X. Use solver 'highs' for example.")
    if self.solver_options is None and self.solver == 'interior-point':
        solver_options = {'lstsq': True}
    else:
        solver_options = self.solver_options
    indices = np.nonzero(sample_weight)[0]
    n_indices = len(indices)
    if n_indices < len(sample_weight):
        sample_weight = sample_weight[indices]
        X = _safe_indexing(X, indices)
        y = _safe_indexing(y, indices)
    c = np.concatenate([np.full(2 * n_params, fill_value=alpha), sample_weight * self.quantile, sample_weight * (1 - self.quantile)])
    if self.fit_intercept:
        c[0] = 0
        c[n_params] = 0
    if self.solver in ['highs', 'highs-ds', 'highs-ipm']:
        eye = _sparse_eye_array(n_indices, dtype=X.dtype, format='csc')
        if self.fit_intercept:
            ones = sparse.csc_array(np.ones(shape=(n_indices, 1), dtype=X.dtype))
            A_eq = sparse.hstack([ones, X, -ones, -X, eye, -eye], format='csc')
        else:
            A_eq = sparse.hstack([X, -X, eye, -eye], format='csc')
    else:
        eye = np.eye(n_indices)
        if self.fit_intercept:
            ones = np.ones((n_indices, 1))
            A_eq = np.concatenate([ones, X, -ones, -X, eye, -eye], axis=1)
        else:
            A_eq = np.concatenate([X, -X, eye, -eye], axis=1)
    b_eq = y
    result = linprog(c=c, A_eq=A_eq, b_eq=b_eq, method=self.solver, options=solver_options)
    solution = result.x
    if not result.success:
        failure = {1: 'Iteration limit reached.', 2: 'Problem appears to be infeasible.', 3: 'Problem appears to be unbounded.', 4: 'Numerical difficulties encountered.'}
        warnings.warn(f'Linear programming for QuantileRegressor did not succeed.\nStatus is {result.status}: ' + failure.setdefault(result.status, 'unknown reason') + '\n' + 'Result message of linprog:\n' + result.message, ConvergenceWarning)
    params = solution[:n_params] - solution[n_params:2 * n_params]
    self.n_iter_ = result.nit
    if self.fit_intercept:
        self.coef_ = params[1:]
        self.intercept_ = params[0]
    else:
        self.coef_ = params
        self.intercept_ = 0.0
    return self

def combine(self, other: DataFrame, func: Callable[[Series, Series], Series | Hashable], fill_value=None, overwrite: bool=True) -> DataFrame:
    other_idxlen = len(other.index)
    other_columns = other.columns
    this, other = self.align(other)
    new_index = this.index
    if other.empty and len(new_index) == len(self.index):
        return self.copy()
    if self.empty and len(other) == other_idxlen:
        return other.copy()
    new_columns = self.columns.union(other_columns, sort=False)
    this = this.reindex(new_columns, axis=1)
    other = other.reindex(new_columns, axis=1)
    do_fill = fill_value is not None
    result = {}
    for i in range(this.shape[1]):
        series = this.iloc[:, i]
        other_series = other.iloc[:, i]
        this_dtype = series.dtype
        other_dtype = other_series.dtype
        this_mask = isna(series)
        other_mask = isna(other_series)
        if not overwrite and other_mask.all():
            result[i] = series.copy()
            continue
        if do_fill:
            series = series.copy()
            other_series = other_series.copy()
            series[this_mask] = fill_value
            other_series[other_mask] = fill_value
        if new_columns[i] not in self.columns:
            new_dtype = other_dtype
            try:
                series = series.astype(new_dtype)
            except ValueError:
                pass
        else:
            new_dtype = find_common_type([this_dtype, other_dtype])
            series = series.astype(new_dtype)
            other_series = other_series.astype(new_dtype)
        arr = func(series, other_series)
        if isinstance(new_dtype, np.dtype):
            arr = maybe_downcast_to_dtype(arr, new_dtype)
        result[i] = arr
    frame_result = self._constructor(result, index=new_index)
    frame_result.columns = new_columns
    return frame_result.__finalize__(self, method='combine')

