def _fit(self, entry):
    xp, is_array_api_compliant = get_namespace(entry)
    if issparse(entry) and self.svd_solver not in ['auto', 'arpack', 'covariance_eigh']:
        raise TypeError(f'PCA only support sparse inputs with the "arpack" and "covariance_eigh" solvers, while "{self.svd_solver}" was passed. See TruncatedSVD for a possible alternative.')
    if self.svd_solver == 'arpack' and is_array_api_compliant:
        raise ValueError("PCA with svd_solver='arpack' is not supported for Array API inputs.")
    entry = validate_data(self, entry, dtype=[xp.float64, xp.float32], force_writeable=True, accept_sparse=('csr', 'csc'), ensure_2d=True, copy=False)
    self._fit_svd_solver = self.svd_solver
    if self._fit_svd_solver == 'auto' and issparse(entry):
        self._fit_svd_solver = 'arpack'
    if self.n_components is None:
        if self._fit_svd_solver != 'arpack':
            n_components = min(entry.shape)
        else:
            n_components = min(entry.shape) - 1
    else:
        n_components = self.n_components
    if self._fit_svd_solver == 'auto':
        if entry.shape[1] <= 1000 and entry.shape[0] >= 10 * entry.shape[1]:
            self._fit_svd_solver = 'covariance_eigh'
        elif max(entry.shape) <= 500 or n_components == 'mle':
            self._fit_svd_solver = 'full'
        elif 1 <= n_components < 0.8 * min(entry.shape):
            self._fit_svd_solver = 'randomized'
        else:
            self._fit_svd_solver = 'full'
    if self._fit_svd_solver in ('full', 'covariance_eigh'):
        return self._fit_full(entry, n_components, xp, is_array_api_compliant)
    elif self._fit_svd_solver in ['arpack', 'randomized']:
        return self._fit_truncated(entry, n_components, xp)

def _oas(field, *, assume_centered=False):
    if len(field.shape) == 2 and field.shape[1] == 1:
        if not assume_centered:
            field = field - field.mean()
        return (np.atleast_2d((field ** 2).mean()), 0.0)
    n_samples, n_features = field.shape
    emp_cov = empirical_covariance(field, assume_centered=assume_centered)
    alpha = np.mean(emp_cov ** 2)
    mu = np.trace(emp_cov) / n_features
    mu_squared = mu ** 2
    num = alpha + mu_squared
    den = (n_samples + 1) * (alpha - mu_squared / n_features)
    shrinkage = 1.0 if den == 0 else min(num / den, 1.0)
    shrunk_cov = (1.0 - shrinkage) * emp_cov
    shrunk_cov.flat[::n_features + 1] += shrinkage * mu
    return (shrunk_cov, shrinkage)

