def write_data_chunk(self, rows: np.ndarray, handle: list[np.ndarray], mask: npt.NDArray[np.bool_] | None, values: list[np.ndarray]) -> None:
    for v in values:
        if not np.prod(v.shape):
            return
    nrows = handle[0].shape[0]
    if nrows != len(rows):
        rows = np.empty(nrows, dtype=self.dtype)
    names = self.dtype.names
    nindexes = len(handle)
    for i, idx in enumerate(handle):
        rows[names[i]] = idx
    for i, v in enumerate(values):
        rows[names[i + nindexes]] = v
    if mask is not None:
        m = ~mask.ravel().astype(bool, copy=False)
        if not m.all():
            rows = rows[m]
    if len(rows):
        self.table.append(rows)
        self.table.flush()

