def setitem(self, indexer, val) -> Block:
    val = self._standardize_fill_value(val)
    values = cast('np.ndarray', self.values)
    if self.ndim == 2:
        values = values.T
    check_setitem_lengths(indexer, val, values)
    if self.dtype != _dtype_obj:
        val = extract_array(val, extract_numpy=True)
    try:
        casted = np_can_hold_element(values.dtype, val)
    except LossySetitemError:
        nb = self.coerce_to_target_dtype(val, raise_on_upcast=True)
        return nb.setitem(indexer, val)
    else:
        if self.dtype == _dtype_obj and (not is_scalar_indexer(indexer, values.ndim)):
            if isinstance(indexer, (ABCSeries, ABCIndex, np.ndarray, list, range, slice)):
                num_set = length_of_indexer(indexer, values)
            else:
                num_set = len(values[indexer])
            casted = setitem_datetimelike_compat(values, num_set, casted)
            if isinstance(casted, list) and len(casted) > 0 and isinstance(casted[0], (tuple, list, np.ndarray)):
                casted = construct_1d_object_array_from_listlike(casted)
        self = self._maybe_copy(inplace=True)
        values = cast('np.ndarray', self.values.T)
        if isinstance(casted, np.ndarray) and casted.ndim == 1 and (len(casted) == 1):
            casted = casted[0, ...]
