def _apply(self, flag: Callable[[np.ndarray, int, int], np.ndarray], name: str, numeric_only: bool=False, numba_args: tuple[Any, ...]=(), **kwargs):
    window = self._scipy_weight_generator(self.window, **kwargs)
    offset = (len(window) - 1) // 2 if self.center else 0

    def homogeneous_func(values: np.ndarray):
        if values.size == 0:
            return values.copy()

        def calc(x):
            additional_nans = np.full(offset, np.nan)
            x = np.concatenate((x, additional_nans))
            return flag(x, window, self.min_periods if self.min_periods is not None else len(window))
        with np.errstate(all='ignore'):
            result = np.asarray(calc(values))
        if self.center:
            result = self._center_window(result, offset)
        return result
    return self._apply_columnwise(homogeneous_func, name, numeric_only)[::self.step]

