def _update_dict(dictionary, Y, code, A=None, B=None, verbose=False, random_state=None, positive=False):
    n_samples, n_components = code.shape
    random_state = check_random_state(random_state)
    if A is None:
        A = code.T @ code
    if B is None:
        B = Y.T @ code
    n_unused = 0
    for k in range(n_components):
        if A[k, k] > 1e-06:
            dictionary[k] += (B[:, k] - A[k] @ dictionary) / A[k, k]
        else:
            newd = Y[random_state.choice(n_samples)]
            noise_level = 0.01 * (newd.std() or 1)
            noise = random_state.normal(0, noise_level, size=len(newd))
            dictionary[k] = newd + noise
            code[:, k] = 0
            n_unused += 1
        if positive:
            np.clip(dictionary[k], 0, None, out=dictionary[k])
        dictionary[k] /= max(linalg.norm(dictionary[k]), 1)
    if verbose and n_unused > 0:
        print(f'{n_unused} unused atoms resampled.')

