def css_calc(item, left: float, right: float, align: str, color: str | list | tuple):
    if pd.isna(item):
        return base_css
    if isinstance(color, (list, tuple)):
        color = color[0] if item < 0 else color[1]
    assert isinstance(color, str)
    item = left if item < left else item
    item = right if item > right else item
    start: float = 0
    end: float = 1
    if align == 'left':
        end = (item - left) / (right - left)
    elif align == 'right':
        start = (item - left) / (right - left)
    else:
        z_frac: float = 0.5
        if align == 'zero':
            limit: float = max(abs(left), abs(right))
            left, right = (-limit, limit)
        elif align == 'mid':
            mid: float = (left + right) / 2
            z_frac = -mid / (right - left) + 0.5 if mid < 0 else -left / (right - left)
        if item < 0:
            start, end = ((item - left) / (right - left), z_frac)
        else:
            start, end = (z_frac, (item - left) / (right - left))
    ret = css_bar(start * width, end * width, color)
    if height < 1 and 'background: linear-gradient(' in ret:
        return ret + f' no-repeat center; background-size: 100% {height * 100:.1f}%;'
    else:
        return ret

