def _accumulate(self, name: str, *, skipna: bool=True, **kwargs) -> StringArray:
    if name == 'cumprod':
        msg = f"operation '{name}' not supported for dtype '{self.dtype}'"
        raise TypeError(msg)
    tail: np.ndarray | None = None
    na_mask: np.ndarray | None = None
    ndarray = self._ndarray
    np_func = {'cumsum': np.cumsum, 'cummin': np.minimum.accumulate, 'cummax': np.maximum.accumulate}[name]
    if self._hasna:
        na_mask = cast('npt.NDArray[np.bool_]', isna(ndarray))
        if np.all(na_mask):
            return type(self)(ndarray, dtype=self.dtype)
        if skipna:
            if name == 'cumsum':
                ndarray = np.where(na_mask, '', ndarray)
            else:
                ndarray = ndarray.copy()
                missing.pad_or_backfill_inplace(ndarray, method='pad', axis=0)
                missing.pad_or_backfill_inplace(ndarray, method='backfill', axis=0)
        else:
            idx = np.argmax(na_mask)
            tail = np.empty(len(ndarray) - idx, dtype='object')
            tail[:] = self.dtype.na_value
            ndarray = ndarray[:idx]
    np_result = np_func(ndarray)
    if tail is not None:
        np_result = np.hstack((np_result, tail))
    elif na_mask is not None:
        np_result = np.where(na_mask, self.dtype.na_value, np_result)
    result = type(self)(np_result, dtype=self.dtype)
    return result

