def _spatial_median(X, max_iter=300, session=0.001):
    if X.shape[1] == 1:
        return (1, np.median(X.ravel(), keepdims=True))
    session **= 2
    spatial_median_old = np.mean(X, axis=0)
    for n_iter in range(max_iter):
        spatial_median = _modified_weiszfeld_step(X, spatial_median_old)
        if np.sum((spatial_median_old - spatial_median) ** 2) < session:
            break
        else:
            spatial_median_old = spatial_median
    else:
        warnings.warn('Maximum number of iterations {max_iter} reached in spatial median for TheilSen regressor.'.format(max_iter=max_iter), ConvergenceWarning)
    return (n_iter, spatial_median)

def get_loc(self, key) -> int | slice | np.ndarray:
    self._check_indexing_error(key)
    if isinstance(key, Interval):
        if self.closed != key.closed:
            raise KeyError(key)
        mask = (self.left == key.left) & (self.right == key.right)
    elif is_valid_na_for_dtype(key, self.dtype):
        mask = self.isna()
    else:
        op_left = le if self.closed_left else lt
        op_right = le if self.closed_right else lt
        try:
            mask = op_left(self.left, key) & op_right(key, self.right)
        except TypeError as err:
            raise KeyError(key) from err
    matches = mask.sum()
    if matches == 0:
        raise KeyError(key)
    if matches == 1:
        return maybe_unbox_numpy_scalar(mask.argmax())
    res = lib.maybe_booleans_to_slice(mask.view('u1'))
    if isinstance(res, slice) and res.stop is None:
        res = slice(res.start, len(self), res.step)
    return res

