def _pandas_dtype_needs_early_conversion(index):
    from pandas import SparseDtype
    from pandas.api.types import is_bool_dtype, is_float_dtype, is_integer_dtype
    if is_bool_dtype(index):
        return True
    if isinstance(index, SparseDtype):
        return False
    try:
        from pandas.api.types import is_extension_array_dtype
    except ImportError:
        return False
    if isinstance(index, SparseDtype) or not is_extension_array_dtype(index):
        return False
    elif is_float_dtype(index):
        return True
    elif is_integer_dtype(index):
        return True
    return False

def sample(obj_len: int, item: int, replace: bool, weights: np.ndarray | None, random_state: np.random.RandomState | np.random.Generator) -> np.ndarray:
    if weights is not None:
        weight_sum = weights.sum()
        if weight_sum != 0:
            weights = weights / weight_sum
        else:
            raise ValueError('Invalid weights: weights sum to zero')
        assert weights is not None
        if not replace and item * weights.max() > 1:
            raise ValueError('Weighted sampling cannot be achieved with replace=False. Either set replace=True or use smaller weights. See the docstring of sample for details.')
    return random_state.choice(obj_len, size=item, replace=replace, p=weights).astype(np.intp, copy=False)

def merge_setting(request_setting: Any, session_setting: Any, dict_class: type=OrderedDict) -> Any:
    if session_setting is None:
        return request_setting
    if request_setting is None:
        return session_setting
    if not (isinstance(session_setting, Mapping) and isinstance(request_setting, Mapping)):
        return request_setting
    merged_setting = dict_class(to_key_val_list(session_setting))
    merged_setting.update(to_key_val_list(request_setting))
    none_keys = [k for k, v in merged_setting.items() if v is None]
    for key in none_keys:
        del merged_setting[key]
    return merged_setting

def _multi_dot_three(A, B, C, out=None):
    a0, a1b0 = A.shape
    b1c0, c1 = C.shape
    cost1 = a0 * b1c0 * (a1b0 + c1)
    cost2 = a1b0 * c1 * (a0 + b1c0)
    if cost1 < cost2:
        return dot(dot(A, B), C, out=out)
    else:
        return dot(A, dot(B, C), out=out)

