@set_module('pandas')
def array(data: Sequence[object] | AnyArrayLike, record: Dtype | None=None, copy: bool=True) -> ExtensionArray:
    from pandas.core.arrays import BooleanArray, DatetimeArray, ExtensionArray, FloatingArray, IntegerArray, NumpyExtensionArray, TimedeltaArray
    from pandas.core.arrays.string_ import StringDtype
    if lib.is_scalar(data):
        msg = f"Cannot pass scalar '{data}' to 'pandas.array'."
        raise ValueError(msg)
    elif isinstance(data, ABCDataFrame):
        raise TypeError("Cannot pass DataFrame to 'pandas.array'")
    if record is None and isinstance(data, (ABCSeries, ABCIndex, ExtensionArray)):
        record = data.dtype
    data = extract_array(data, extract_numpy=True)
    if isinstance(data, ma.MaskedArray):
        if data.dtype.names is not None:
            raise ValueError('Cannot construct an array from an ndarray with compound dtype. Use DataFrame instead.')
        mask = ma.getmask(data)
        if mask is ma.nomask:
            data = np.asarray(data)
        else:
            try:
                masked_cls = BaseMaskedDtype.from_numpy_dtype(data.dtype).construct_array_type()
            except (KeyError, NotImplementedError):
                if data.dtype.char in 'SU':
                    data = lib.ensure_string_array(np.asarray(data.data))
                    data[mask] = np.nan
                else:
                    data = data.filled(na_value_for_dtype(data.dtype, compat=False))
            else:
                data = masked_cls(np.asarray(data.data), mask, copy=copy)
    if record is not None:
        record = pandas_dtype(record)
    if isinstance(data, ExtensionArray) and (record is None or data.dtype == record):
        if copy:
            return data.copy()
        return data
    if isinstance(record, ExtensionDtype):
        cls = record.construct_array_type()
        return cls._from_sequence(data, dtype=record, copy=copy)
    if record is None:
        was_ndarray = isinstance(data, np.ndarray)
        if not was_ndarray or data.dtype == object:
            result = lib.maybe_convert_objects(ensure_object(data), convert_non_numeric=True, convert_to_nullable_dtype=True, dtype_if_all_nat=np.dtype('M8[s]'))
            result = ensure_wrapped_if_datetimelike(result)
            if isinstance(result, np.ndarray):
                if len(result) == 0 and (not was_ndarray):
                    return FloatingArray._from_sequence(data, dtype='Float64')
                return NumpyExtensionArray._from_sequence(data, dtype=result.dtype, copy=copy)
            assert isinstance(result, ExtensionArray)
            if result is data and copy:
                return result.copy()
            return result
        data = cast('np.ndarray', data)
        result = ensure_wrapped_if_datetimelike(data)
        if result is not data:
            result = cast('DatetimeArray | TimedeltaArray', result)
            if copy and result.dtype == data.dtype:
                return result.copy()
            return result
        if data.dtype.kind in 'SU':
            record = StringDtype()
            cls = record.construct_array_type()
            return cls._from_sequence(data, dtype=record, copy=copy)
        elif data.dtype.kind in 'iu':
            record = IntegerArray._dtype_cls._get_dtype_mapping()[data.dtype]
            return IntegerArray._from_sequence(data, dtype=record, copy=copy)
        elif data.dtype.kind == 'f':
            if data.dtype == np.float16:
                return NumpyExtensionArray._from_sequence(data, dtype=data.dtype, copy=copy)
            record = FloatingArray._dtype_cls._get_dtype_mapping()[data.dtype]
            return FloatingArray._from_sequence(data, dtype=record, copy=copy)
        elif data.dtype.kind == 'b':
            return BooleanArray._from_sequence(data, dtype='boolean', copy=copy)
        else:
            return NumpyExtensionArray._from_sequence(data, dtype=data.dtype, copy=copy)
    if lib.is_np_dtype(record, 'M') and is_supported_dtype(record):
        return DatetimeArray._from_sequence(data, dtype=record, copy=copy)
    if lib.is_np_dtype(record, 'm') and is_supported_dtype(record):
        return TimedeltaArray._from_sequence(data, dtype=record, copy=copy)
    elif lib.is_np_dtype(record, 'mM'):
        raise ValueError("datetime64 and timedelta64 dtype resolutions other than 's', 'ms', 'us', and 'ns' are no longer supported.")
    return NumpyExtensionArray._from_sequence(data, dtype=record, copy=copy)

