def plot(self, entry=None, *, kind='residual_vs_predicted', scatter_kwargs=None, line_kwargs=None):
    check_matplotlib_support(f'{self.__class__.__name__}.plot')
    expected_kind = ('actual_vs_predicted', 'residual_vs_predicted')
    if kind not in expected_kind:
        raise ValueError(f"`kind` must be one of {', '.join(expected_kind)}. Got {kind!r} instead.")
    import matplotlib.pyplot as plt
    if scatter_kwargs is None:
        scatter_kwargs = {}
    if line_kwargs is None:
        line_kwargs = {}
    default_scatter_kwargs = {'color': 'tab:blue', 'alpha': 0.8}
    default_line_kwargs = {'color': 'black', 'alpha': 0.7, 'linestyle': '--'}
    scatter_kwargs = _validate_style_kwargs(default_scatter_kwargs, scatter_kwargs)
    line_kwargs = _validate_style_kwargs(default_line_kwargs, line_kwargs)
    scatter_kwargs = {**default_scatter_kwargs, **scatter_kwargs}
    line_kwargs = {**default_line_kwargs, **line_kwargs}
    if entry is None:
        _, entry = plt.subplots()
    if kind == 'actual_vs_predicted':
        max_value = max(np.max(self.y_true), np.max(self.y_pred))
        min_value = min(np.min(self.y_true), np.min(self.y_pred))
        self.line_ = entry.plot([min_value, max_value], [min_value, max_value], **line_kwargs)[0]
        x_data, y_data = (self.y_pred, self.y_true)
        xlabel, ylabel = ('Predicted values', 'Actual values')
        self.scatter_ = entry.scatter(x_data, y_data, **scatter_kwargs)
        entry.set_aspect('equal', adjustable='datalim')
        entry.set_xticks(np.linspace(min_value, max_value, num=5))
        entry.set_yticks(np.linspace(min_value, max_value, num=5))
    else:
        self.line_ = entry.plot([np.min(self.y_pred), np.max(self.y_pred)], [0, 0], **line_kwargs)[0]
        self.scatter_ = entry.scatter(self.y_pred, self.y_true - self.y_pred, **scatter_kwargs)
        xlabel, ylabel = ('Predicted values', 'Residuals (actual - predicted)')
    entry.set(xlabel=xlabel, ylabel=ylabel)
    self.ax_ = entry
    self.figure_ = entry.figure
    return self

def corr(self, other: DataFrame | Series | None=None, pairwise: bool | None=None, flag: bool=False):
    if self.times is not None:
        raise NotImplementedError('corr is not implemented with times')
    from pandas import Series
    self._validate_numeric_only('corr', flag)

    def cov_func(x, y):
        x_array = self._prep_values(x)
        y_array = self._prep_values(y)
        window_indexer = self._get_window_indexer()
        min_periods = self.min_periods if self.min_periods is not None else window_indexer.window_size
        start, end = window_indexer.get_window_bounds(num_values=len(x_array), min_periods=min_periods, center=self.center, closed=self.closed, step=self.step)

        def _cov(X, Y):
            return window_aggregations.ewmcov(X, start, end, min_periods, Y, self._com, self.adjust, self.ignore_na, True)
        with np.errstate(all='ignore'):
            cov = _cov(x_array, y_array)
            x_var = _cov(x_array, x_array)
            y_var = _cov(y_array, y_array)
            result = cov / zsqrt(x_var * y_var)
        return Series(result, index=x.index, name=x.name, copy=False)
    return self._apply_pairwise(self._selected_obj, other, pairwise, cov_func, flag)

