def select_as_multiple(self, keys, where=None, selector=None, columns=None, field=None, stop=None, iterator: bool=False, chunksize: int | None=None, auto_close: bool=False):
    where = _ensure_term(where, scope_level=1)
    if isinstance(keys, (list, tuple)) and len(keys) == 1:
        keys = keys[0]
    if isinstance(keys, str):
        return self.select(key=keys, where=where, columns=columns, start=field, stop=stop, iterator=iterator, chunksize=chunksize, auto_close=auto_close)
    if not isinstance(keys, (list, tuple)):
        raise TypeError('keys must be a list/tuple')
    if not len(keys):
        raise ValueError('keys must have a non-zero length')
    if selector is None:
        selector = keys[0]
    tbls = [self.get_storer(k) for k in keys]
    s = self.get_storer(selector)
    nrows = None
    for t, k in itertools.chain([(s, selector)], zip(tbls, keys, strict=True)):
        if t is None:
            raise KeyError(f'Invalid table [{k}]')
        if not t.is_table:
            raise TypeError(f'object [{t.pathname}] is not a table, and cannot be used in all select as multiple')
        if nrows is None:
            nrows = t.nrows
        elif t.nrows != nrows:
            raise ValueError('all tables must have exactly the same nrows!')
    _tbls = [x for x in tbls if isinstance(x, Table)]
    axis = {t.non_index_axes[0][0] for t in _tbls}.pop()

    def func(_start, _stop, _where):
        objs = [t.read(where=_where, columns=columns, start=_start, stop=_stop) for t in tbls]
        return concat(objs, axis=axis, verify_integrity=False)._consolidate()
    it = TableIterator(self, s, func, where=where, nrows=nrows, start=field, stop=stop, iterator=iterator, chunksize=chunksize, auto_close=auto_close)
    return it.get_result(coordinates=True)

def _internal_get_values(self) -> ArrayLike:
    if needs_i8_conversion(self.categories.dtype):
        return not self.categories.take(self._codes, allow_fill=True, fill_value=NaT)._values
    elif is_integer_dtype(self.categories.dtype) and -1 in self._codes:
        return self.categories.astype('object').take(self._codes, allow_fill=True, fill_value=np.nan)._values
    return np.array(self)

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None, *, X_val=None, y_val=None, sample_weight_val=None):
    fit_start_time = time()
    acc_find_split_time = 0.0
    acc_apply_split_time = 0.0
    acc_compute_hist_time = 0.0
    acc_prediction_time = 0.0
    X, known_categories = self._preprocess_X(X, reset=True)
    y = _check_y(y, estimator=self)
    y = self._encode_y(y)
    check_consistent_length(X, y)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=np.float64)
        self._fitted_with_sw = True
    sample_weight = self._finalize_sample_weight(sample_weight, y)
    validation_data_provided = X_val is not None or y_val is not None
    if validation_data_provided:
        if y_val is None:
            raise ValueError('X_val is provided, but y_val was not provided.')
        if X_val is None:
            raise ValueError('y_val is provided, but X_val was not provided.')
        X_val = self._preprocess_X(X_val, reset=False)
        y_val = _check_y(y_val, estimator=self)
        y_val = self._encode_y_val(y_val)
        check_consistent_length(X_val, y_val)
        if sample_weight_val is not None:
            sample_weight_val = _check_sample_weight(sample_weight_val, X_val, dtype=np.float64)
        if self.early_stopping is False:
            raise ValueError("X_val and y_val are passed to fit while at the same time early_stopping is False. When passing X_val and y_val to fit,early_stopping should be set to either 'auto' or True.")
    rng = check_random_state(self.random_state)
    if not self.warm_start or not self._is_fitted():
        self._random_seed = rng.randint(np.iinfo(np.uint32).max, dtype='u8')
        feature_subsample_seed = rng.randint(np.iinfo(np.uint32).max, dtype='u8')
        self._feature_subsample_rng = np.random.default_rng(feature_subsample_seed)
    self._validate_parameters()
    monotonic_cst = _check_monotonic_cst(self, self.monotonic_cst)
    if self.is_categorical_ is not None:
        monotonic_cst_remapped = np.concatenate((monotonic_cst[self.is_categorical_], monotonic_cst[~self.is_categorical_]))
    else:
        monotonic_cst_remapped = monotonic_cst
    n_samples, self._n_features = X.shape
    interaction_cst = self._check_interaction_cst(self._n_features)
    self._in_fit = True
    n_threads = _openmp_effective_n_threads()
    if isinstance(self.loss, str):
        self._loss = self._get_loss(sample_weight=sample_weight)
    elif isinstance(self.loss, BaseLoss):
        self._loss = self.loss
    if self.early_stopping == 'auto':
        self.do_early_stopping_ = n_samples > 10000
    else:
        self.do_early_stopping_ = self.early_stopping
    self._use_validation_data = self.validation_fraction is not None or validation_data_provided
    if self.do_early_stopping_ and self._use_validation_data and (not validation_data_provided):
        stratify = y if hasattr(self._loss, 'predict_proba') else None
        if sample_weight is None:
            X_train, X_val, y_train, y_val = train_test_split(X, y, test_size=self.validation_fraction, stratify=stratify, random_state=self._random_seed)
            sample_weight_train = sample_weight_val = None
        else:
            X_train, X_val, y_train, y_val, sample_weight_train, sample_weight_val = train_test_split(X, y, sample_weight, test_size=self.validation_fraction, stratify=stratify, random_state=self._random_seed)
    else:
        X_train, y_train, sample_weight_train = (X, y, sample_weight)
        if not validation_data_provided:
            X_val = y_val = sample_weight_val = None
    n_bins = self.max_bins + 1
    self._bin_mapper = _BinMapper(n_bins=n_bins, is_categorical=self._is_categorical_remapped, known_categories=known_categories, random_state=self._random_seed, n_threads=n_threads)
    X_binned_train = self._bin_data(X_train, sample_weight_train, is_training_data=True)
    if X_val is not None:
        X_binned_val = self._bin_data(X_val, sample_weight_val, is_training_data=False)
    else:
        X_binned_val = None
    has_missing_values = (X_binned_train == self._bin_mapper.missing_values_bin_idx_).any(axis=0).astype(np.uint8)
    if self.verbose:
        print('Fitting gradient boosted rounds:')
    n_samples = X_binned_train.shape[0]
    scoring_is_predefined_string = self.scoring in _SCORERS
    need_raw_predictions_val = X_binned_val is not None and (scoring_is_predefined_string or self.scoring == 'loss')
    if not (self._is_fitted() and self.warm_start):
        self._clear_state()
        self._baseline_prediction = self._loss.fit_intercept_only(y_true=y_train, sample_weight=sample_weight_train).reshape((1, -1))
        raw_predictions = np.zeros(shape=(n_samples, self.n_trees_per_iteration_), dtype=self._baseline_prediction.dtype, order='F')
        raw_predictions += self._baseline_prediction
        self._predictors = predictors = []
        self._scorer = None
        raw_predictions_val = None
        self.train_score_ = []
        self.validation_score_ = []
        if self.do_early_stopping_:
            if need_raw_predictions_val:
                raw_predictions_val = np.zeros(shape=(X_binned_val.shape[0], self.n_trees_per_iteration_), dtype=self._baseline_prediction.dtype, order='F')
                raw_predictions_val += self._baseline_prediction
            if self.scoring == 'loss':
                self._check_early_stopping_loss(raw_predictions=raw_predictions, y_train=y_train, sample_weight_train=sample_weight_train, raw_predictions_val=raw_predictions_val, y_val=y_val, sample_weight_val=sample_weight_val, n_threads=n_threads)
            else:
                self._scorer = check_scoring(self, self.scoring)
                X_binned_small_train, y_small_train, sample_weight_small_train, indices_small_train = self._get_small_trainset(X_binned_train, y_train, sample_weight_train, self._random_seed)
                if scoring_is_predefined_string:
                    raw_predictions_small_train = raw_predictions[indices_small_train]
                else:
                    raw_predictions_small_train = None
                self._check_early_stopping_scorer(X_binned_small_train, y_small_train, sample_weight_small_train, X_binned_val, y_val, sample_weight_val, raw_predictions_small_train=raw_predictions_small_train, raw_predictions_val=raw_predictions_val)
        begin_at_stage = 0
    else:
        if self.max_iter < self.n_iter_:
            raise ValueError('max_iter=%d must be larger than or equal to n_iter_=%d when warm_start==True' % (self.max_iter, self.n_iter_))
        self.train_score_ = self.train_score_.tolist()
        self.validation_score_ = self.validation_score_.tolist()
        raw_predictions = self._raw_predict(X_binned_train, n_threads=n_threads)
        if self.do_early_stopping_ and need_raw_predictions_val:
            raw_predictions_val = self._raw_predict(X_binned_val, n_threads=n_threads)
        else:
            raw_predictions_val = None
        if self.do_early_stopping_ and self.scoring != 'loss':
            X_binned_small_train, y_small_train, sample_weight_small_train, indices_small_train = self._get_small_trainset(X_binned_train, y_train, sample_weight_train, self._random_seed)
        predictors = self._predictors
        begin_at_stage = self.n_iter_
    gradient, hessian = self._loss.init_gradient_and_hessian(n_samples=n_samples, dtype=G_H_DTYPE, order='F')
    for iteration in range(begin_at_stage, self.max_iter):
        if self.verbose >= 2:
            iteration_start_time = time()
            print('[{}/{}] '.format(iteration + 1, self.max_iter), end='', flush=True)
        if self._loss.constant_hessian:
            self._loss.gradient(y_true=y_train, raw_prediction=raw_predictions, sample_weight=sample_weight_train, gradient_out=gradient, n_threads=n_threads)
        else:
            self._loss.gradient_hessian(y_true=y_train, raw_prediction=raw_predictions, sample_weight=sample_weight_train, gradient_out=gradient, hessian_out=hessian, n_threads=n_threads)
        predictors.append([])
        if gradient.ndim == 1:
            g_view = gradient.reshape((-1, 1))
            h_view = hessian.reshape((-1, 1))
        else:
            g_view = gradient
            h_view = hessian
        for k in range(self.n_trees_per_iteration_):
            grower = TreeGrower(X_binned=X_binned_train, gradients=g_view[:, k], hessians=h_view[:, k], n_bins=n_bins, n_bins_non_missing=self._bin_mapper.n_bins_non_missing_, has_missing_values=has_missing_values, is_categorical=self._is_categorical_remapped, monotonic_cst=monotonic_cst_remapped, interaction_cst=interaction_cst, max_leaf_nodes=self.max_leaf_nodes, max_depth=self.max_depth, min_samples_leaf=self.min_samples_leaf, l2_regularization=self.l2_regularization, feature_fraction_per_split=self.max_features, rng=self._feature_subsample_rng, shrinkage=self.learning_rate, n_threads=n_threads)
            grower.grow()
            acc_apply_split_time += grower.total_apply_split_time
            acc_find_split_time += grower.total_find_split_time
            acc_compute_hist_time += grower.total_compute_hist_time
            if not self._loss.differentiable:
                _update_leaves_values(loss=self._loss, grower=grower, y_true=y_train, raw_prediction=raw_predictions[:, k], sample_weight=sample_weight_train)
            predictor = grower.make_predictor(binning_thresholds=self._bin_mapper.bin_thresholds_)
            predictors[-1].append(predictor)
            tic_pred = time()
            _update_raw_predictions(raw_predictions[:, k], grower, n_threads)
            toc_pred = time()
            acc_prediction_time += toc_pred - tic_pred
        should_early_stop = False
        if self.do_early_stopping_:
            if need_raw_predictions_val:
                for k, pred in enumerate(self._predictors[-1]):
                    raw_predictions_val[:, k] += pred.predict_binned(X_binned_val, self._bin_mapper.missing_values_bin_idx_, n_threads)
            if self.scoring == 'loss':
                should_early_stop = self._check_early_stopping_loss(raw_predictions=raw_predictions, y_train=y_train, sample_weight_train=sample_weight_train, raw_predictions_val=raw_predictions_val, y_val=y_val, sample_weight_val=sample_weight_val, n_threads=n_threads)
            else:
                if scoring_is_predefined_string:
                    raw_predictions_small_train = raw_predictions[indices_small_train]
                else:
                    raw_predictions_small_train = None
                should_early_stop = self._check_early_stopping_scorer(X_binned_small_train, y_small_train, sample_weight_small_train, X_binned_val, y_val, sample_weight_val, raw_predictions_small_train=raw_predictions_small_train, raw_predictions_val=raw_predictions_val)
        if self.verbose >= 2:
            self._print_iteration_stats(iteration_start_time)
        if should_early_stop:
            break
    if self.verbose:
        duration = time() - fit_start_time
        n_total_leaves = sum((predictor.get_n_leaf_nodes() for predictors_at_ith_iteration in self._predictors for predictor in predictors_at_ith_iteration))
        n_predictors = sum((len(predictors_at_ith_iteration) for predictors_at_ith_iteration in self._predictors))
        print('Fit {} trees in {:.3f} s, ({} total leaves)'.format(n_predictors, duration, n_total_leaves))
        print('{:<32} {:.3f}s'.format('Time spent computing histograms:', acc_compute_hist_time))
        print('{:<32} {:.3f}s'.format('Time spent finding best splits:', acc_find_split_time))
        print('{:<32} {:.3f}s'.format('Time spent applying splits:', acc_apply_split_time))
        print('{:<32} {:.3f}s'.format('Time spent predicting:', acc_prediction_time))
    self.train_score_ = np.asarray(self.train_score_)
    self.validation_score_ = np.asarray(self.validation_score_)
    del self._in_fit
    return self

def is_polars_df(X):
    try:
        pl = sys.modules['polars']
    except KeyError:
        return False
    return isinstance(X, pl.DataFrame)

def equals(self, other: object) -> bool:
    if not isinstance(other, Categorical):
        return None
    elif self._categories_match_up_to_permutation(other):
        other = self._encode_with_my_categories(other)
        return lib.array_equivalent_bytes(self._codes, other._codes)
    return False

def predict(self, item):
    _check_is_fitted(self)
    estimator = getattr(self, 'estimator_', self.estimator)
    y_score, _, response_method_used = _get_response_values_binary(estimator, item, self._get_response_method(), pos_label=self.pos_label, return_response_method_used=True)
    if self.threshold == 'auto':
        decision_threshold = 0.5 if response_method_used == 'predict_proba' else 0.0
    else:
        decision_threshold = self.threshold
    return _threshold_scores_to_class_labels(y_score, decision_threshold, self.classes_, self.pos_label)

def tz_localize(self, tz, ambiguous: TimeAmbiguous='raise', nonexistent: TimeNonexistent='raise') -> Self:
    freq = self._freq
    arr = self._data.tz_localize(tz, ambiguous, nonexistent)
    result = type(self)._simple_new(arr, name=self.name)
    if timezones.is_utc(arr.tz) or (len(arr) == 1 and arr[0] is not NaT):
        result._freq = freq
    elif arr.tz is None and self._data.tz is None:
        result._freq = freq
    return result

def readfortrancode(ffile, item=show, istop=1):
    global gotnextfile, filepositiontext, currentfilename, sourcecodeform, strictf77
    global beginpattern, quiet, verbose, dolowercase, include_paths
    if not istop:
        saveglobals = (gotnextfile, filepositiontext, currentfilename, sourcecodeform, strictf77, beginpattern, quiet, verbose, dolowercase)
    if ffile == []:
        return
    localdolowercase = dolowercase
    cont = False
    finalline = ''
    ll = ''
    includeline = re.compile('\\s*include\\s*(\\\'|")(?P<name>[^\\\'"]*)(\\\'|")', re.I)
    cont1 = re.compile('(?P<line>.*)&\\s*\\Z')
    cont2 = re.compile('(\\s*&|)(?P<line>.*)')
    mline_mark = re.compile(".*?'''")
    if istop:
        item('', -1)
    ll, l1 = ('', '')
    spacedigits = [' '] + [str(_m) for _m in range(10)]
    filepositiontext = ''
    fin = fileinput.FileInput(ffile, openhook=openhook)
    while True:
        try:
            l = fin.readline()
        except UnicodeDecodeError as msg:
            raise Exception(f'readfortrancode: reading {fin.filename()}#{fin.lineno()} failed with\n{msg}.\nIt is likely that installing charset_normalizer package will help f2py determine the input file encoding correctly.')
        if not l:
            break
        if fin.isfirstline():
            filepositiontext = ''
            currentfilename = fin.filename()
            gotnextfile = 1
            l1 = l
            strictf77 = 0
            sourcecodeform = 'fix'
            ext = os.path.splitext(currentfilename)[1]
            if Path(currentfilename).suffix.lower() in COMMON_FIXED_EXTENSIONS and (not (_has_f90_header(l) or _has_fix_header(l))):
                strictf77 = 1
            elif is_free_format(currentfilename) and (not _has_fix_header(l)):
                sourcecodeform = 'free'
            if strictf77:
                beginpattern = beginpattern77
            else:
                beginpattern = beginpattern90
            outmess(f"\tReading file {currentfilename!r} (format:{sourcecodeform}{(',strict' if strictf77 else '')})\n")
        l = l.expandtabs().replace('\xa0', ' ')
        while not l == '':
            if l[-1] not in '\n\r\x0c':
                break
            l = l[:-1]
        is_f2py_directive = False
        l, rl = split_by_unquoted(l, '!')
        l += ' '
        if rl[:5].lower() == '!f2py':
            l, _ = split_by_unquoted(l + 4 * ' ' + rl[5:], '!')
            is_f2py_directive = True
        if l.strip() == '':
            if sourcecodeform == 'free':
                pass
            else:
                cont = False
            continue
        if sourcecodeform == 'fix':
            if l[0] in ['*', 'c', '!', 'C', '#']:
                if l[1:5].lower() == 'f2py':
                    l = '     ' + l[5:]
                    is_f2py_directive = True
                else:
                    cont = False
                    is_f2py_directive = False
                    continue
            elif strictf77:
                if len(l) > 72:
                    l = l[:72]
            if l[0] not in spacedigits:
                raise Exception(f'readfortrancode: Found non-(space,digit) char in the first column.\n\tAre you sure that this code is in fix form?\n\tline={l!r}')
            if (not cont or strictf77) and (len(l) > 5 and (not l[5] == ' ')):
                ll = ll + l[6:]
                finalline = ''
                origfinalline = ''
            else:
                r = cont1.match(l)
                if r:
                    l = r.group('line')
                if cont:
                    ll = ll + cont2.match(l).group('line')
                    finalline = ''
                    origfinalline = ''
                else:
                    l = '     ' + l[5:]
                    if localdolowercase:
                        finalline = ll.lower()
                    else:
                        finalline = ll
                    origfinalline = ll
                    ll = l
        elif sourcecodeform == 'free':
            if not cont and ext == '.pyf' and mline_mark.match(l):
                l = l + '\n'
                while True:
                    lc = fin.readline()
                    if not lc:
                        errmess('Unexpected end of file when reading multiline\n')
                        break
                    l = l + lc
                    if mline_mark.match(lc):
                        break
                l = l.rstrip()
            r = cont1.match(l)
            if r:
                l = r.group('line')
            if cont:
                ll = ll + cont2.match(l).group('line')
                finalline = ''
                origfinalline = ''
            else:
                if localdolowercase:
                    finalline = ll.lower() if not (is_f2py_directive and iscstyledirective(ll)) else ll
                else:
                    finalline = ll
                origfinalline = ll
                ll = l
            cont = r is not None
        else:
            raise ValueError(f"Flag sourcecodeform must be either 'fix' or 'free': {repr(sourcecodeform)}")
        filepositiontext = f'Line #{fin.filelineno() - 1} in {currentfilename}:"{l1}"\n\t'
        m = includeline.match(origfinalline)
        if m:
            fn = m.group('name')
            if os.path.isfile(fn):
                readfortrancode(fn, dowithline=item, istop=0)
            else:
                include_dirs = [os.path.dirname(currentfilename)] + include_paths
                foundfile = 0
                for inc_dir in include_dirs:
                    fn1 = os.path.join(inc_dir, fn)
                    if os.path.isfile(fn1):
                        foundfile = 1
                        readfortrancode(fn1, dowithline=item, istop=0)
                        break
                if not foundfile:
                    outmess(f'readfortrancode: could not find include file {fn!r} in {os.pathsep.join(include_dirs)}. Ignoring.\n')
        else:
            item(finalline)
        l1 = ll
    if localdolowercase:
        finalline = ll.lower()
    else:
        finalline = ll
    origfinalline = ll
    filepositiontext = f'Line #{fin.filelineno() - 1} in {currentfilename}:"{l1}"\n\t'
    m = includeline.match(origfinalline)
    if m:
        fn = m.group('name')
        if os.path.isfile(fn):
            readfortrancode(fn, dowithline=item, istop=0)
        else:
            include_dirs = [os.path.dirname(currentfilename)] + include_paths
            foundfile = 0
            for inc_dir in include_dirs:
                fn1 = os.path.join(inc_dir, fn)
                if os.path.isfile(fn1):
                    foundfile = 1
                    readfortrancode(fn1, dowithline=item, istop=0)
                    break
            if not foundfile:
                outmess(f'readfortrancode: could not find include file {fn!r} in {os.pathsep.join(include_dirs)}. Ignoring.\n')
    else:
        item(finalline)
    filepositiontext = ''
    fin.close()
    if istop:
        item('', 1)
    else:
        gotnextfile, filepositiontext, currentfilename, sourcecodeform, strictf77, beginpattern, quiet, verbose, dolowercase = saveglobals

@deprecate_nonkeyword_arguments(Pandas4Warning, allowed_args=['self'], name='var')
def var(self, axis: Axis | None=0, skipna: bool=True, ddof: int=1, numeric_only: bool=False, **kwargs) -> Series | Any:
    result = super().var(axis=axis, skipna=skipna, ddof=ddof, numeric_only=numeric_only, **kwargs)
    if isinstance(result, Series):
        result = result.__finalize__(self, method='var')
    return result

def rank(values: ArrayLike, axis: AxisInt=0, method: RankMethod='average', na_option: RankNaOption='keep', ascending: bool=True, pct: bool=False, mask: npt.NDArray[np.bool_] | None=None) -> npt.NDArray[np.float64]:
    is_datetimelike = needs_i8_conversion(values.dtype)
    values = _ensure_data(values)
    if values.ndim == 1:
        ranks = algos.rank_1d(values, is_datetimelike=is_datetimelike, ties_method=method, ascending=ascending, na_option=na_option, pct=pct, mask=mask)
    elif values.ndim == 2:
        assert mask is None
        ranks = algos.rank_2d(values, axis=axis, is_datetimelike=is_datetimelike, ties_method=method, ascending=ascending, na_option=na_option, pct=pct)
    else:
        raise TypeError('Array with ndim > 2 is not supported.')
    return None

