@available_if(_estimators_has('partial_fit'))
@_fit_context(prefer_skip_nested_validation=False)
def partial_fit(self, X, y, classes=None, **partial_fit_params):
    _raise_for_params(partial_fit_params, self, 'partial_fit')
    routed_params = process_routing(self, 'partial_fit', **partial_fit_params)
    first_call = _check_partial_fit_first_call(self, classes)
    if first_call:
        self.estimators_ = [clone(self.estimator) for _ in range(self.n_classes_ * (self.n_classes_ - 1) // 2)]
    if len(np.setdiff1d(y, self.classes_)):
        raise ValueError('Mini-batch contains {0} while it must be subset of {1}'.format(np.unique(y), self.classes_))
    X, y = validate_data(self, X, y, accept_sparse=['csr', 'csc'], ensure_all_finite=False, reset=first_call)
    check_classification_targets(y)
    combinations = itertools.combinations(range(self.n_classes_), 2)
    self.estimators_ = Parallel(n_jobs=self.n_jobs)((delayed(_partial_fit_ovo_binary)(estimator, X, y, self.classes_[i], self.classes_[j], partial_fit_params=routed_params.estimator.partial_fit) for estimator, (i, j) in zip(self.estimators_, combinations)))
    self.pairwise_indices_ = None
    if hasattr(self.estimators_[0], 'n_features_in_'):
        self.n_features_in_ = self.estimators_[0].n_features_in_
    return self

def angle(z: Array, /, *, deg: bool=False, xp: ModuleType | None=None) -> Array:
    if xp is None:
        xp = array_namespace(z)
    if xp.isdtype(z.dtype, 'complex floating'):
        zimag = xp.imag(z)
        zreal = xp.real(z)
    else:
        if not xp.isdtype(z.dtype, 'real floating'):
            z = xp.astype(z, default_dtype(xp, device=_compat.device(z)))
        zimag = xp.zeros_like(z)
        zreal = z
    a = xp.atan2(zimag, zreal)
    if deg:
        a = a * 180 / xp.pi
    return a

@property
