def eager_shape(x: Array, /, axis: int | None=None) -> tuple[int, ...]:
    shape = x.shape
    if axis is not None:
        s = shape[axis]
        if s is None or math.isnan(s):
            msg = f'Unsupported lazy shape for axis {axis}'
            raise TypeError(msg)
        return (s,)
