def describe_numeric_1d(series: Series, percentiles: Sequence[float]) -> Series:
    from pandas import Series
    formatted_percentiles = format_percentiles(percentiles)
    if len(percentiles) == 0:
        quantiles = []
    else:
        quantiles = series.quantile(percentiles).tolist()
    stat_index = ['count', 'mean', 'std', 'min', *formatted_percentiles, 'max']
    d = [series.count(), series.mean(), series.std(), series.min(), *quantiles, series.max()]
    dtype: DtypeObj | None
    if isinstance(series.dtype, ExtensionDtype):
        if isinstance(series.dtype, ArrowDtype):
            if series.dtype.kind == 'm':
                dtype = None
            else:
                import pyarrow as pa
                dtype = ArrowDtype(pa.float64())
        else:
            dtype = Float64Dtype()
    elif series.dtype.kind in 'iufb':
        dtype = np.dtype('float')
    else:
        dtype = None
    return Series(d, index=stat_index, name=series.name, dtype=dtype)

def predict(self, param_62):
    neigh_dist, neigh_ind = self.radius_neighbors(param_62)
    weights = _get_weights(neigh_dist, self.weights)
    _y = self._y
    if _y.ndim == 1:
        _y = _y.reshape((-1, 1))
    empty_obs = np.full_like(_y[0], np.nan)
    if weights is None:
        y_pred = np.array([np.mean(_y[ind, :], axis=0) if len(ind) else empty_obs for i, ind in enumerate(neigh_ind)])
    else:
        y_pred = np.array([np.average(_y[ind, :], axis=0, weights=weights[i]) if len(ind) else empty_obs for i, ind in enumerate(neigh_ind)])
    if np.any(np.isnan(y_pred)):
        empty_warning_msg = 'One or more samples have no neighbors within specified radius; predicting NaN.'
        warnings.warn(empty_warning_msg)
    if self._y.ndim == 1:
        y_pred = y_pred.ravel()
    return y_pred

def to_period(self, freq=None) -> PeriodArray:
    from pandas.core.arrays import PeriodArray
    if self.tz is not None:
