def safe_sparse_dot(a, b, *, dense_output=False):
    xp, _ = get_namespace(a, b)
    if a.ndim > 2 or b.ndim > 2:
        if sparse.issparse(a):
            b_ = np.rollaxis(b, -2)
            b_2d = b_.reshape((b.shape[-2], -1))
            ret = a @ b_2d
            ret = ret.reshape(a.shape[0], *b_.shape[1:])
        elif sparse.issparse(b):
            a_2d = a.reshape(-1, a.shape[-1])
            ret = a_2d @ b
            ret = ret.reshape(*a.shape[:-1], b.shape[1])
        else:
            b_axis = -1 if b.ndim == 1 else -2
            ret = xp.tensordot(a, b, axes=[-1, b_axis])
    elif dense_output and a.ndim == 2 and (b.ndim == 2) and (sparse.issparse(a) and a.format in ('csc', 'csr')) and (sparse.issparse(b) and b.format in ('csc', 'csr')) and (a.dtype in (np.float32, np.float64)) and (b.dtype in (np.float32, np.float64)):
        return sparse_matmul_to_dense(a, b)
    else:
        ret = a @ b
    if sparse.issparse(a) and sparse.issparse(b) and dense_output and hasattr(ret, 'toarray'):
        return ret.toarray()
    return ret

