def _estimate_gaussian_parameters(X, resp, reg_covar, covariance_type, xp=None):
    xp, _ = get_namespace(X, xp=xp)
    nk = xp.sum(resp, axis=0) + 10 * xp.finfo(resp.dtype).eps
    means = resp.T @ X / nk[:, xp.newaxis]
    covariances = {'full': _estimate_gaussian_covariances_full, 'tied': _estimate_gaussian_covariances_tied, 'diag': _estimate_gaussian_covariances_diag, 'spherical': _estimate_gaussian_covariances_spherical}[covariance_type](resp, X, nk, means, reg_covar, xp=xp)
    return (nk, means, covariances)

