def _prepare_categoricals(self, param_30: DataFrame) -> DataFrame:
    is_cat = [isinstance(dtype, CategoricalDtype) for dtype in param_30.dtypes]
    if not any(is_cat):
        return param_30
    self._has_value_labels |= np.array(is_cat)
    get_base_missing_value = StataMissingValue.get_base_missing_value
    data_formatted = []
    for col, col_is_cat in zip(param_30, is_cat, strict=True):
        if col_is_cat:
            svl = StataValueLabel(param_30[col], encoding=self._encoding)
            self._value_labels.append(svl)
            dtype = param_30[col].cat.codes.dtype
            if dtype == np.int64:
                raise ValueError('It is not possible to export int64-based categorical data to Stata.')
            values = param_30[col].cat.codes._values.copy()
            if values.max() >= get_base_missing_value(dtype):
                if dtype == np.int8:
                    dtype = np.dtype(np.int16)
                elif dtype == np.int16:
                    dtype = np.dtype(np.int32)
                else:
                    dtype = np.dtype(np.float64)
                values = np.array(values, dtype=dtype)
            values[values == -1] = get_base_missing_value(dtype)
            data_formatted.append((col, values))
        else:
            data_formatted.append((col, param_30[col]))
    return DataFrame.from_dict(dict(data_formatted))

