def _inclusive_low_high(interval):
    eps = 10 * ulp(1)
    if interval.low == -float('inf'):
        low = -10000000000.0
    elif interval.low < 0:
        low = interval.low * (1 - eps) + eps
    else:
        low = interval.low * (1 + eps) + eps
    if interval.high == float('inf'):
        high = 10000000000.0
    elif interval.high < 0:
        high = interval.high * (1 + eps) - eps
    else:
        high = interval.high * (1 - eps) - eps
    return (float(low), float(high))

