def fit(self, X, y, sample_weight=None, score_params=None):
    xp, is_array_api, device_ = get_namespace_and_device(X)
    y, sample_weight = move_to(y, sample_weight, xp=xp, device=device_)
    if is_array_api and xp.isdtype(X.dtype, 'real floating') or getattr(getattr(X, 'dtype', None), 'kind', None) == 'f':
        original_floating_dtype = X.dtype
    else:
        original_floating_dtype = None
    dtype = _max_precision_float_dtype(xp, device=device_)
    X, y = validate_data(self, X, y, accept_sparse=['csr', 'csc', 'coo'], dtype=dtype, multi_output=True, y_numeric=True)
    assert not (self.is_clf and self.alpha_per_target)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X, dtype=X.dtype)
    self.alphas = np.asarray(self.alphas)
    unscaled_y = y
    X, y, X_offset, y_offset, X_scale, sqrt_sw = _preprocess_data(X, y, fit_intercept=self.fit_intercept, copy=self.copy_X, sample_weight=sample_weight, rescale_with_sw=True)
    gcv_mode = _check_gcv_mode(X, self.gcv_mode)
    n_samples, n_features = X.shape
    if gcv_mode == 'gram':
        decompose = self._eigen_decompose_gram
        solve = self._solve_eigen_gram
    elif gcv_mode == 'cov':
        decompose = self._eigen_decompose_covariance
        solve = self._solve_eigen_covariance
    elif gcv_mode == 'svd':
        decompose = self._svd_decompose_design_matrix
        solve = self._solve_svd_design_matrix
    else:
        raise ValueError(f'Unknown gcv_mode={gcv_mode!r}')
    if sqrt_sw is None:
        sqrt_sw = xp.ones(n_samples, dtype=X.dtype, device=device_)
    decomposition = decompose(X, X_offset, y, sqrt_sw)
    n_y = 1 if y.ndim == 1 else y.shape[1]
    if isinstance(self.alphas, numbers.Number) or getattr(self.alphas, 'ndim', None) == 0:
        alphas = [float(self.alphas)]
    else:
        alphas = list(map(float, self.alphas))
    n_alphas = len(alphas)
    if self.store_cv_results:
        self.cv_results_ = xp.empty((n_samples * n_y, n_alphas), dtype=X.dtype, device=device_)
    best_coef, best_score, best_alpha = (None, None, None)
    for i, alpha in enumerate(alphas):
        looe, coef = solve(float(alpha), y, sqrt_sw, *decomposition)
        if self.scoring is None:
            squared_errors = looe ** 2
            alpha_score = self._score_without_scorer(squared_errors=squared_errors)
            if self.store_cv_results:
                self.cv_results_[:, i] = _ravel(squared_errors)
        else:
            predictions = y - looe
            if sample_weight is not None:
                if predictions.ndim > 1:
                    predictions /= sqrt_sw[:, None]
                else:
                    predictions /= sqrt_sw
            predictions += y_offset
            if self.store_cv_results:
                self.cv_results_[:, i] = _ravel(predictions)
            score_params = score_params or {}
            alpha_score = self._score(predictions=predictions, y=unscaled_y, n_y=n_y, scorer=self.scoring, score_params=score_params)
        if best_score is None:
            if self.alpha_per_target and n_y > 1:
                best_coef = coef
                best_score = xp.reshape(alpha_score, shape=(-1,))
                best_alpha = xp.full(n_y, alpha, device=device_)
            else:
                best_coef = coef
                best_score = alpha_score
                best_alpha = alpha
        elif self.alpha_per_target and n_y > 1:
            to_update = alpha_score > best_score
            best_coef[:, to_update] = coef[:, to_update]
            best_score[to_update] = alpha_score[to_update]
            best_alpha[to_update] = alpha
        elif alpha_score > best_score:
            best_coef, best_score, best_alpha = (coef, alpha_score, alpha)
    self.alpha_ = best_alpha
    self.best_score_ = best_score
    self.coef_ = best_coef
    if y.ndim == 2:
        self.coef_ = self.coef_.T
    if y.ndim == 1 or y.shape[1] == 1:
        self.coef_ = _ravel(self.coef_)
    self._set_intercept(X_offset, y_offset, X_scale)
    if self.store_cv_results:
        if y.ndim == 1:
            cv_results_shape = (n_samples, n_alphas)
        else:
            cv_results_shape = (n_samples, n_y, n_alphas)
        self.cv_results_ = xp.reshape(self.cv_results_, shape=cv_results_shape)
    if original_floating_dtype:
        if type(self.intercept_) is not float:
            self.intercept_ = xp.astype(self.intercept_, original_floating_dtype, copy=False)
        self.coef_ = xp.astype(self.coef_, original_floating_dtype, copy=False)
        if self.store_cv_results:
            self.cv_results_ = xp.astype(self.cv_results_, original_floating_dtype, copy=False)
    return self

def _fit(self, X, y, max_samples=None, max_depth=None, check_input=True, sample_weight=None, **fit_params):
    random_state = check_random_state(self.random_state)
    n_samples = X.shape[0]
    self._n_samples = n_samples
    y = self._validate_y(y)
    self._validate_estimator(self._get_estimator())
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        routed_params = _manual_routing({'estimator': {'fit': fit_params}})
    if max_depth is not None:
        self.estimator_.max_depth = max_depth
    if max_samples is None:
        max_samples = self.max_samples
    max_samples = _get_n_samples_bootstrap(X.shape[0], max_samples, sample_weight)
    if not self.bootstrap and max_samples > X.shape[0]:
        raise ValueError(f'Effective max_samples={max_samples} must be <= n_samples={X.shape[0]} to be able to sample without replacement.')
    self._max_samples = max_samples
    if isinstance(self.max_features, numbers.Integral):
        max_features = self.max_features
    elif isinstance(self.max_features, float):
        max_features = int(self.max_features * self.n_features_in_)
    if max_features > self.n_features_in_:
        raise ValueError('max_features must be <= n_features')
    max_features = max(1, int(max_features))
    self._max_features = max_features
    self._sample_weight = sample_weight
    if not self.bootstrap and self.oob_score:
        raise ValueError('Out of bag estimation only available if bootstrap=True')
    if self.warm_start and self.oob_score:
        raise ValueError('Out of bag estimate only available if warm_start=False')
    if hasattr(self, 'oob_score_') and self.warm_start:
        del self.oob_score_
    if not self.warm_start or not hasattr(self, 'estimators_'):
        self.estimators_ = []
        self.estimators_features_ = []
    n_more_estimators = self.n_estimators - len(self.estimators_)
    if n_more_estimators < 0:
        raise ValueError('n_estimators=%d must be larger or equal to len(estimators_)=%d when warm_start==True' % (self.n_estimators, len(self.estimators_)))
    elif n_more_estimators == 0:
        warn('Warm-start fitting without increasing n_estimators does not fit new trees.')
        return self
    n_jobs, n_estimators, starts = _partition_estimators(n_more_estimators, self.n_jobs)
    total_n_estimators = sum(n_estimators)
    if self.warm_start and len(self.estimators_) > 0:
        random_state.randint(MAX_INT, size=len(self.estimators_))
    seeds = random_state.randint(MAX_INT, size=n_more_estimators)
    self._seeds = seeds
    all_results = Parallel(n_jobs=n_jobs, verbose=self.verbose, **self._parallel_args())((delayed(_parallel_build_estimators)(n_estimators[i], self, X, y, sample_weight, seeds[starts[i]:starts[i + 1]], total_n_estimators, verbose=self.verbose, check_input=check_input, fit_params=routed_params.estimator.fit) for i in range(n_jobs)))
    self.estimators_ += list(itertools.chain.from_iterable((t[0] for t in all_results)))
    self.estimators_features_ += list(itertools.chain.from_iterable((t[1] for t in all_results)))
    if self.oob_score:
        self._set_oob_score(X, y)
    return self

def _safe_fill_null(arr: pa.Array | pa.ChunkedArray, fill_value: Any) -> pa.Array | pa.ChunkedArray:
    import pyarrow.compute as pc
    is_windows = sys.platform in ['win32', 'cygwin']
    use_fallback = HAS_PYARROW and is_windows and (not pa_version_under21p0) and pa_version_under22p0
    if not use_fallback or isinstance(fill_value, (pa.Array, pa.ChunkedArray)):
        return pc.fill_null(arr, fill_value)
    fill_scalar = pa.scalar(fill_value, type=arr.type)
    if pa.types.is_duration(arr.type):

        def fill_null_duration(arr: pa.Array, fill_scalar: pa.Scalar) -> pa.Array:
            mask = pc.is_null(arr)
            zero_duration = pa.scalar(0, type=arr.type)
            arr_zeroed = pc.if_else(mask, zero_duration, arr)
            return pc.if_else(mask, fill_scalar, arr_zeroed)
        if isinstance(arr, pa.ChunkedArray):
            return pa.chunked_array([fill_null_duration(chunk, fill_scalar) for chunk in arr.chunks])
        return fill_null_duration(arr, fill_scalar)
    if isinstance(arr, pa.ChunkedArray):
        return pa.chunked_array([pc.if_else(pc.is_null(chunk), fill_scalar, chunk) for chunk in arr.chunks])
    return pc.if_else(pc.is_null(arr), fill_scalar, arr)

