def load_files(container_path, *, description=None, categories=None, load_content=True, shuffle=True, encoding=None, decode_error='strict', random_state=0, allowed_extensions=None):
    target = []
    target_names = []
    filenames = []
    folders = [f for f in sorted(listdir(container_path)) if isdir(join(container_path, f))]
    if categories is not None:
        folders = [f for f in folders if f in categories]
    if allowed_extensions is not None:
        allowed_extensions = frozenset(allowed_extensions)
    for label, folder in enumerate(folders):
        target_names.append(folder)
        folder_path = join(container_path, folder)
        files = sorted(listdir(folder_path))
        if allowed_extensions is not None:
            documents = [join(folder_path, file) for file in files if os.path.splitext(file)[1] in allowed_extensions]
        else:
            documents = [join(folder_path, file) for file in files]
        target.extend(len(documents) * [label])
        filenames.extend(documents)
    filenames = np.array(filenames)
    target = np.array(target)
    if shuffle:
        random_state = check_random_state(random_state)
        indices = np.arange(filenames.shape[0])
        random_state.shuffle(indices)
        filenames = filenames[indices]
        target = target[indices]
    if load_content:
        data = []
        for filename in filenames:
            data.append(Path(filename).read_bytes())
        if encoding is not None:
            data = [d.decode(encoding, decode_error) for d in data]
        return Bunch(data=data, filenames=filenames, target_names=target_names, target=target, DESCR=description)
    return Bunch(filenames=filenames, target_names=target_names, target=target, DESCR=description)

