        dists = cdist(X / length_scale, field / length_scale, metric='euclidean')
    if self.nu == 0.5:
        K = np.exp(-dists)
    elif self.nu == 1.5:
        K = dists * math.sqrt(3)
        K = (1.0 + K) * np.exp(-K)
    elif self.nu == 2.5:
        K = dists * math.sqrt(5)
        K = (1.0 + K + K ** 2 / 3.0) * np.exp(-K)
    elif self.nu == np.inf:
        K = np.exp(-dists ** 2 / 2.0)
    else:
        K = dists
        K[K == 0.0] += np.finfo(float).eps
        tmp = math.sqrt(2 * self.nu) * K
        K.fill(2 ** (1.0 - self.nu) / gamma(self.nu))
        K *= tmp ** self.nu
        K *= kv(self.nu, tmp)
    if field is None:
        K = squareform(K)
        np.fill_diagonal(K, 1)
    if eval_gradient:
        if self.hyperparameter_length_scale.fixed:
            K_gradient = np.empty((X.shape[0], X.shape[0], 0))
            return (K, K_gradient)
        if self.anisotropic:
            D = (X[:, np.newaxis, :] - X[np.newaxis, :, :]) ** 2 / length_scale ** 2
        else:
            D = squareform(dists ** 2)[:, :, np.newaxis]
        if self.nu == 0.5:
            denominator = np.sqrt(D.sum(axis=2))[:, :, np.newaxis]
            divide_result = np.zeros_like(D)
            np.divide(D, denominator, out=divide_result, where=denominator != 0)
            K_gradient = K[..., np.newaxis] * divide_result
        elif self.nu == 1.5:
            K_gradient = 3 * D * np.exp(-np.sqrt(3 * D.sum(-1)))[..., np.newaxis]
        elif self.nu == 2.5:
            tmp = np.sqrt(5 * D.sum(-1))[..., np.newaxis]
            K_gradient = 5.0 / 3.0 * D * (tmp + 1) * np.exp(-tmp)
        elif self.nu == np.inf:
            K_gradient = D * K[..., np.newaxis]
        else:

            def f(theta):
                return self.clone_with_theta(theta)(X, field)
            return (K, _approx_fprime(self.theta, f, 1e-10))
        if not self.anisotropic:
            return (K, K_gradient[:, :].sum(-1)[:, :, np.newaxis])
        else:
            return (K, K_gradient)
    else:
        return K

@deprecate_nonkeyword_arguments(Pandas4Warning, allowed_args=['self'], name='sem')
def sem(self, axis: Axis | None=None, skipna: bool=True, ddof: int=1, numeric_only: bool=False, **kwargs):
