@final
def round(self, decimals: int) -> Self:
    if not self.is_numeric or self.is_bool:
        if isinstance(self.values, (DatetimeArray, TimedeltaArray, PeriodArray)):
            warnings.warn('obj.round has no effect with datetime, timedelta, or period dtypes. Use obj.dt.round(...) instead.', UserWarning, stacklevel=find_stack_level())
        return self.copy(deep=False)
    values = self.values.round(decimals)
    refs = None
    if values is self.values:
        refs = self.refs
    return self.make_block_same_class(values, refs=refs)

